/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A29 frozen manifest: elusively–engrave (80 headwords), authored in exact order. */
'use strict';
const D = globalThis.RA.D;
const E = (origin,w) => ({origin,prefix:null,root:null,suffix:null,source:'Etymonline — https://www.etymonline.com/word/'+w.toLowerCase()});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M = (wrong,right,reason,errorType='meaning') => ({wrong,right,reason,errorType});
const Q = (w,n,s,p,a,b,c,x,errorType='meaning') => ({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const P = (w,origin,ctx,wrong,right,reason,qs,type='meaning') => D(w,{etymology:E(origin,w),contexts:[ctx],mistakes:[M(wrong,right,reason,type)],quiz:qs});
P('elusively','elusively is formed from elusive plus -ly; elusive derives from Latin eludere, “to evade or escape.”',C('elusively.s1','访谈','Asked to name the source, the witness smiled elusively and changed the subject, leaving the reporter without a direct answer.','被问及消息来源时，证人意味难明地笑了笑并转移话题，没有给记者直接答复。','Asked to name the source / the witness smiled elusively / and changed the subject / leaving the reporter without a direct answer.','副词 elusively 修饰 smiled，说明笑容难以解读；也可修饰回答或移动方式。','转移话题且未给明确回答，体现躲闪、难以把握的 s1。'),'The witness answered elusively by giving a clear name and precise address.','The witness answered directly by giving a clear name and precise address.','给出明确姓名和地址是直接回答，不是躲闪地回答。',[
Q('elusively',1,1,'A person who answers elusively is most likely to?','avoid giving a clear answer','repeat every detail plainly','read a written address aloud','elusively 表示回答躲闪或难以捉摸。'),Q('elusively',2,1,'Which action is described as elusively?','A suspect slips through a crowd without being identified.','A guide marks each turn on a map.','A student states the date exactly.','悄然避开辨认符合 elusively。'),Q('elusively',3,1,'In “the concept is elusively defined,” elusively suggests the concept is?','hard to pin down','already measured precisely','easy to classify','它表示难以清楚界定。'),Q('elusively',4,1,'Choose the best completion: The politician spoke elusively, so reporters?','still could not tell what she promised','copied a precise written pledge','heard an unambiguous yes','模糊措辞使记者仍无法确定承诺。')]);
P('elusiveness','elusiveness is formed from elusive plus the noun-forming suffix -ness; elusive came through French from Latin eludere, “evade.”',C('elusiveness.s1','文学评论','The elusiveness of the poem’s central image invites several readings, since no single interpretation explains every detail.','诗歌核心意象的难以捉摸引出了多种解读，因为没有一种解释能说明所有细节。','The elusiveness of the poem’s central image / invites several readings / since no single interpretation explains every detail.','名词 elusiveness 常接 of，表示人、事物或概念难以被捕捉或定义的性质。','意象不能被单一解释穷尽，体现抽象概念难以界定的 s1。'),'The elusiveness of the answer was obvious because it gave the exact location and time.','The clarity of the answer was obvious because it gave the exact location and time.','精确交代地点和时间表示清楚明确，不是 elusiveness。',[
Q('elusiveness',1,1,'The elusiveness of a suspect makes the suspect difficult to?','locate or catch','identify from a clear photograph','question after an arrest','elusiveness 指难以找到或抓住的性质。'),Q('elusiveness',2,1,'A theory has elusiveness when it is?','hard to define precisely','supported by one simple measurement','written in large letters','难以精确定义是概念的 elusiveness。'),Q('elusiveness',3,1,'Which noun is closest in meaning to elusiveness here?','evasiveness','certainty','visibility','evasiveness 表示躲避或难以捉摸。'),Q('elusiveness',4,1,'A reader notes the elusiveness of a character’s motives. The motives are?','not easy to understand or pin down','openly stated in a confession','unrelated to the story','动机难以把握，符合此词义。')]);
P('emaciate','emaciate entered English from Latin emaciare, “make lean,” from macer, “lean.”',C('emaciate.s1','饥荒报道','Months without adequate food emaciated the cattle, whose ribs showed through their coats when aid workers reached the valley.','数月食物不足使牛群消瘦不堪；救援人员到达山谷时，它们的肋骨已透过皮毛显露出来。','Months without adequate food / emaciated the cattle / whose ribs showed through their coats / when aid workers reached the valley.','emaciate 是及物动词，主语通常是饥饿、疾病等原因；常见被动 be emaciated。','缺粮导致牛瘦到肋骨显露，符合使人或动物极度消瘦的 s1。'),'The illness emaciated the patient by making her gain healthy muscle and weight.','The illness strengthened the patient by helping her gain healthy muscle and weight.','增肌增重与 emaciate 所指的病态消瘦相反。',[
Q('emaciate',1,1,'A prolonged famine may emaciate livestock by?','leaving them dangerously thin','making them gain fat rapidly','giving them thicker coats','emaciate 表示使动物因饥饿而极瘦。'),Q('emaciate',2,1,'Which is a likely result when disease emaciates someone?','The person becomes extremely thin and weak.','The person develops unusually strong muscles.','The person becomes taller overnight.','疾病造成的严重消瘦是该动词的结果。'),Q('emaciate',3,1,'In “the drought emaciated the herd,” emaciated is?','a transitive verb with the herd as its object','a noun naming the herd','an adverb modifying drought','emaciate 可带宾语，herd 是被使消瘦的对象。'),Q('emaciate',4,1,'Choose the correct use: Months of hunger?','emaciated the rescued dog','emaciated a full water bowl','emaciated the bright paint color','长期饥饿能使狗极度消瘦。')]);
P('emaciated','emaciated is the past participle of emaciate, from Latin emaciare, “make lean.”',C('emaciated.s1','动物救助','The emaciated fox had visible ribs and little strength, so the wildlife team moved it to a quiet enclosure for treatment.','那只瘦骨嶙峋的狐狸肋骨清晰可见、几乎没有力气，因此野生动物救援队把它移到安静的围栏里治疗。','The emaciated fox / had visible ribs and little strength / so the wildlife team moved it / to a quiet enclosure for treatment.','emaciated 作形容词，描述因饥饿或疾病而极瘦虚弱的人或动物。','肋骨可见且虚弱是严重消瘦的可观察迹象，符合 s1。'),'The emaciated athlete was robust and visibly heavier after weeks without food.','The undernourished athlete was frail and visibly thinner after weeks without food.','无食数周导致虚弱变瘦，不能称为强壮且明显增重。',[
Q('emaciated',1,1,'An emaciated animal is?','extremely thin and weak','well-fed and unusually heavy','covered in thick new fur only','该形容词表示严重消瘦虚弱。'),Q('emaciated',2,1,'Which evidence best supports calling a horse emaciated?','Its ribs protrude and it is weak.','It has a shiny coat and strong muscles.','It is carrying a heavy saddle.','肋骨突出并虚弱支持严重消瘦的判断。'),Q('emaciated',3,1,'“An emaciated face” most likely looks?','wasted from illness or hunger','round from recent weight gain','painted with bright colors','面部消瘦憔悴是常见搭配。'),Q('emaciated',4,1,'The word emaciated carries which implication?','unhealthy thinness','fashionable slimness without concern','great physical strength','它通常暗示疾病或饥饿造成的不健康消瘦。')]);
P('emanate','emanate comes from Latin emanare, “flow out,” formed from e- “out” and manare “flow.”',C('emanate.s1','实验室','A sharp chemical smell emanated from the sealed cabinet, prompting the technician to clear the room and call the safety officer.','密闭柜里散出刺鼻的化学气味，技术员于是清空房间并通知安全主管。','A sharp chemical smell / emanated from the sealed cabinet / prompting the technician to clear the room / and call the safety officer.','不及物动词 emanate 常与 from 连用，表示气味、光、声音或影响从某处发出。','气味从柜中散出，体现由某来源发出的 s1。'),'A sharp chemical smell emanated into the cabinet from nowhere, with no source to come from.','A sharp chemical smell came from the sealed cabinet.','emanate 表示从来源发出；原句否认来源又说 from，搭配和逻辑矛盾。',[
Q('emanate',1,1,'If warmth emanates from a stove, the warmth?','flows outward from the stove','is stored only inside a freezer','has no possible source','emanate 指从某处向外散出。'),Q('emanate',2,1,'Choose the natural pattern.','A faint melody emanated from the next room.','A faint melody emanated the next room.','A faint melody emanated at the next room.','不及物 emanate 通常接 from 引出来源。'),Q('emanate',3,1,'Which could emanate from a bakery?','the smell of fresh bread','a passport issued by a bank','a mountain range placed indoors','气味可以从面包店散发出来。'),Q('emanate',4,1,'“Authority emanated from her calm manner” means authority?','seemed to arise from her manner','was mailed to her by the manner','was physically inside a letter','抽象影响也可比喻为从某来源显现。')]);
P('emancipation','emancipation derives from Latin emancipare, “release from one’s authority,” from manus “hand” and capere “take.”',C('emancipation.s1','历史','The emancipation of enslaved people required legal change as well as continued efforts to secure safety, education, and equal rights.','被奴役者的解放既需要法律变革，也需要持续保障安全、教育和同等权利的努力。','The emancipation of enslaved people / required legal change / as well as continued efforts / to secure safety, education, and equal rights.','emancipation 是名词，常接 of；表达从奴役、法律依附或严重限制中获得自由。','法律改革和权利保障共同指向摆脱奴役与压迫的 s1。'),'The emancipation of the prisoners meant the guards permanently tightened their chains.','The continued imprisonment of the prisoners meant the guards tightened their chains.','收紧镣铐是继续监禁，与 emancipation 所指的释放相反。',[
Q('emancipation',1,1,'Emancipation from slavery means?','being freed from enslavement','being assigned a new owner','being moved to another prison','emancipation 指从奴役中解放。'),Q('emancipation',2,1,'A campaign for women’s emancipation chiefly seeks?','freedom from legal and social restrictions','a return to legal dependence','the removal of voting rights','该词表示从限制中争取自由与权利。'),Q('emancipation',3,1,'Which phrase uses emancipation naturally?','the emancipation of enslaved people','the emancipation of a locked suitcase lid','the emancipation of a weather forecast','人群从奴役中获得自由是自然语境。'),Q('emancipation',4,1,'Emancipation is closest to?','liberation','captivity','ownership','liberation 是解放、释放。')]);
P('embalm','embalm came through Old French embaumer, originally “put in balm”; balm traces to Latin balsamum.',C('embalm.s1','葬礼准备','Before the funeral, trained staff embalmed the body so it could be preserved for viewing without rapid decay.','葬礼前，受过训练的工作人员为遗体做了防腐处理，使其能保存供瞻仰而不迅速腐败。','Before the funeral / trained staff embalmed the body / so it could be preserved for viewing / without rapid decay.','embalm 通常是及物动词，指用化学处理防止遗体腐败；比喻用法见 s2。','对遗体作防腐处理以减缓腐败，对应字面义 s1。'),'The funeral staff embalmed the body by leaving it untreated in a warm room.','The funeral staff preserved the body with embalming chemicals.','不处理并放在温暖处会加速腐败，不是防腐。',[
Q('embalm',1,1,'To embalm a body is to?','treat it to slow decay','bury it in an unmarked field','paint it for a portrait','embalm 指处理遗体以防腐。'),Q('embalm',2,2,'A writer says a song embalms a childhood memory. The song?','preserves the memory in lasting form','causes the memory to decay physically','removes the memory from everyone','比喻义为保存记忆或故事，不使其被遗忘。'),Q('embalm',3,1,'Which setting most directly calls for embalming?','preparing a body for a funeral viewing','storing fresh vegetables in a fridge','cleaning a bronze statue','遗体葬礼前的保存处理对应字面义。'),Q('embalm',4,1,'In the literal sense, embalming mainly aims to?','delay decomposition','increase decomposition','change a person’s legal identity','防腐目的是延缓遗体腐败。')]);
P('embankment','embankment is formed from embank plus -ment; bank is an old word for a raised edge or mound.',C('embankment.s1','铁路工程','Workers reinforced the embankment beneath the railway after heavy rain loosened soil along the slope.','暴雨冲松斜坡土壤后，工人加固了铁路下方的路堤。','Workers reinforced the embankment / beneath the railway / after heavy rain loosened soil / along the slope.','embankment 作可数名词，可指挡水堤岸或承托铁路、公路的填土高地。','铁路下方被加固的填土坡体符合路堤义 s1。'),'The train crossed an embankment, a deep tunnel carved entirely below ground.','The train crossed an embankment, a raised bank of earth supporting the track.','地下隧道不是高起并承托轨道的路堤。',[
Q('embankment',1,1,'A railway embankment is usually?','raised earth that supports the track','a tunnel far below the track','a signal inside the train','路堤是承托线路的填土高地。'),Q('embankment',2,1,'A river embankment may be built to?','help restrain floodwater','increase the river’s salinity','measure the speed of a train','堤岸能约束河水、帮助防洪。'),Q('embankment',3,1,'Which feature most clearly indicates an embankment?','a raised bank carrying a road over low ground','a flat pond with no raised edge','an underground pipe','高起并承载道路的是路堤。'),Q('embankment',4,1,'After erosion, engineers inspect the embankment for?','weak soil slopes supporting the railway','loose pages in the station timetable','cracks in a passenger’s suitcase','检查对象应是承托铁路的土坡。')]);
P('embarrassment','embarrassment is formed from embarrass plus -ment; embarrass came through French embarrasser, “to hinder or perplex.”',C('embarrassment.s1','公开演讲','Her embarrassment was obvious when she misread the slide, paused, and then corrected herself in front of the audience.','她读错幻灯片后停顿并当着听众的面纠正，尴尬之情显而易见。','Her embarrassment was obvious / when she misread the slide / paused / and then corrected herself in front of the audience.','embarrassment 作不可数情绪名词，也可作“令人难堪的人或事”可数用法。','当众读错并纠正使她感到难为情，符合情绪义 s1。'),'His embarrassment was clear because he felt completely relaxed while receiving praise.','His pride was clear because he felt pleased while receiving praise.','放松地接受赞扬通常不会产生尴尬；pride 更符合此场景。',[
Q('embarrassment',1,1,'A person feels embarrassment after?','making an awkward mistake in public','quietly finishing a familiar task','receiving a clear map','公开犯尴尬错误常使人难为情。'),Q('embarrassment',2,1,'Which reaction most suggests embarrassment?','blushing and wishing to disappear','cheering loudly after a victory','sleeping peacefully','脸红并想躲开是尴尬的常见反应。'),Q('embarrassment',3,1,'In “to my embarrassment,” embarrassment names?','a feeling of awkward shame','a medical instrument','a formal invitation','该短语表示令某人尴尬的是。'),Q('embarrassment',4,1,'A colleague’s embarrassing mistake caused her?','embarrassment','altitude','emigration','错误带来的难为情感是 embarrassment。')]);
P('embellish','embellish entered English through Old French embellir, from bel “beautiful”; figuratively it can mean adding untrue details.',C('embellish.s1','服饰工艺','The tailor embellished the plain jacket with small silver buttons and careful embroidery along the cuffs.','裁缝用小银扣和袖口的精细刺绣装饰了那件素色夹克。','The tailor embellished the plain jacket / with small silver buttons / and careful embroidery along the cuffs.','及物动词 embellish 可表示添加装饰使之更美；讲故事时的“添油加醋”是 s2。','银扣和刺绣让素色夹克更美观，体现装饰义 s1。'),'The plain jacket was embellished by removing every button and decorative stitch.','The plain jacket was simplified by removing every button and decorative stitch.','移除装饰会使衣服变朴素，不是 embellish。',[
Q('embellish',1,1,'To embellish a plain dress is to?','add decorative details','remove every ornament','measure its weight','embellish 的字面义是添加装饰。'),Q('embellish',2,2,'A speaker embellishes a story by?','adding invented details to make it vivid','checking every detail against a record','shortening it without changing facts','故事义指添入不真实细节以使叙述更精彩。'),Q('embellish',3,1,'Which is a literal embellishment?','gold thread sewn around a collar','a missing page in a book','a plain unmarked wall','金线装饰衣领是实际装饰。'),Q('embellish',4,2,'Why might a listener distrust an embellished anecdote?','Some details may have been invented.','Every word must be a verified quotation.','The story has no events.','添油加醋可能加入编造的细节。')]);
P('embezzle','embezzle came from obsolete Anglo-French embesiller, “steal or make away with”; modern use is specifically entrusted funds or property.',C('embezzle.s1','财务调查','The treasurer was charged with embezzling donations that had been entrusted to her for the community shelter.','财务主管被指控侵吞交由她保管、用于社区收容所的捐款。','The treasurer was charged / with embezzling donations / that had been entrusted to her / for the community shelter.','embezzle 是及物动词，关键是非法挪用自己受托管理的钱款或财物。','捐款受托由财务主管保管，却被其私用，符合 s1。'),'The cashier embezzled her own legally earned salary by depositing it in her account.','The cashier received her legally earned salary by depositing it in her account.','合法领取自己的工资不属于挪用受托资金。',[
Q('embezzle',1,1,'A clerk embezzles money when the clerk?','steals funds entrusted for management','receives an approved salary','returns a found wallet','embezzle 的核心是侵吞受托管理的资金。'),Q('embezzle',2,1,'Which case is embezzlement?','An accountant secretly diverts a client’s trust funds.','A customer pays a bill at a shop.','A bank corrects a mistaken deposit.','暗中挪用客户托管资金符合该动词。'),Q('embezzle',3,1,'The verb embezzle usually implies the money was?','under the offender’s responsibility or control','found in an unowned forest','borrowed with clear permission','受托管理或控制是区别普通盗窃的重要背景。'),Q('embezzle',4,1,'Choose a natural object of embezzle.','public funds','a mountain range','a spoken syllable','embezzle 常以资金或财产为宾语。')]);
P('embezzlement','embezzlement is formed from embezzle plus -ment; the verb’s modern legal sense concerns dishonest use of entrusted property.',C('embezzlement.s1','审计','An audit uncovered embezzlement after several transfers from the nonprofit’s account were traced to the director’s private business.','审计发现多笔从非营利组织账户转出的款项流入主管的私人企业，揭露了侵吞公款行为。','An audit uncovered embezzlement / after several transfers from the nonprofit’s account / were traced to the director’s private business.','embezzlement 是对受托管理财产的欺诈性挪用，通常作不可数名词。','组织资金被主管转入私人企业，体现受托财产遭侵吞的 s1。'),'The review found embezzlement because the director openly returned every entrusted payment to its owner.','The review found no embezzlement because the director returned every entrusted payment to its owner.','归还全部受托款项并无挪用；原句因果关系相反。',[
Q('embezzlement',1,1,'Embezzlement involves?','dishonestly taking property one was trusted to manage','ordinary payment of an agreed wage','a legal donation made openly','embezzlement 是侵吞受托管理的财产。'),Q('embezzlement',2,1,'Which document might reveal embezzlement?','an audit tracing diverted company funds','a weather report for the coast','a menu listing lunch prices','审计可追查被挪用的组织资金。'),Q('embezzlement',3,1,'Why is embezzlement distinct from a simple purchase?','The person misuses entrusted funds for personal benefit.','The buyer pays the listed price.','The seller issues a receipt.','受托人挪用钱款是此罪行的关键。'),Q('embezzlement',4,1,'A charity manager secretly uses donated money for personal debts. This is?','embezzlement','reimbursement','fundraising','私用代管捐款符合侵吞义。')]);
P('emblazon','emblazon combines en- with blazon, a heraldic term for a coat of arms; it means display or decorate prominently.',C('emblazon.s1','运动队服','The school emblazoned its crest across the team’s jackets so supporters could recognize the players from the stands.','学校把校徽醒目地印在队服上，让看台上的支持者能认出队员。','The school emblazoned its crest / across the team’s jackets / so supporters could recognize the players / from the stands.','emblazon 是及物动词，常用 emblazon A on/across B，表示醒目地展示或装饰。','校徽被显眼地展示在夹克上，符合 s1。'),'The school emblazoned its crest by hiding it inside an opaque box.','The school concealed its crest inside an opaque box.','藏入不透明盒子是隐藏标志，而不是醒目展示。',[
Q('emblazon',1,1,'To emblazon a badge on a banner is to?','display it prominently','erase it completely','fold the banner into a box','emblazon 表示醒目地绘制或展示。'),Q('emblazon',2,1,'Which phrase uses emblazon naturally?','The sponsor emblazoned its name across the shirts.','The sponsor emblazoned the shirts by deleting their names.','The sponsor emblazoned across the shirts with silence.','名字印在衣服上是常见用法。'),Q('emblazon',3,1,'A coat of arms emblazoned on a shield would be?','clearly displayed as a design','hidden under a thick cover','spoken quietly without being written','该词可指醒目展示徽章图案。'),Q('emblazon',4,1,'Which action best matches emblazon?','printing a bright logo across a vehicle door','washing a logo off a vehicle','parking the vehicle in a garage','醒目印制标志符合 emblazon。')]);
P('embolism','embolism comes through French from Greek embolismos, “insertion,” from embolos “plug or stopper.”',C('embolism.s1','医学影像','The scan revealed a pulmonary embolism, a blockage in a lung vessel caused by material carried through the bloodstream.','影像检查发现了肺栓塞：血流携带的物质堵塞了肺部血管。','The scan revealed a pulmonary embolism / a blockage in a lung vessel / caused by material carried through the bloodstream.','embolism 是医学名词，指血管被随血流移动的物质堵塞；具体类型需由专业诊断。','血流携带物质堵塞肺血管，符合栓塞的 s1。'),'The report called an embolism a vessel made wider by an unobstructed flow of blood.','The report called an embolism a vessel obstruction caused by material in the bloodstream.','血管未受阻且变宽与栓塞所指的堵塞相反。',[
Q('embolism',1,1,'An embolism is a blockage in?','a blood vessel','a healthy tooth enamel layer','an open field path','embolism 指血管发生阻塞。'),Q('embolism',2,1,'A pulmonary embolism affects vessels in the?','lungs','outer ear','fingernails','pulmonary 指肺部，肺栓塞发生在肺血管。'),Q('embolism',3,1,'What may cause an embolism?','material carried through the bloodstream','a harmless sound wave in air','a painted sign on a wall','随血流移动并堵塞血管的物质可导致栓塞。'),Q('embolism',4,1,'In medical usage, embolism is closest to?','vascular obstruction','bone growth','skin pigmentation','它指血管阻塞，而非骨或皮肤变化。')]);
P('embosom','embosom is formed from en- plus bosom, from Old English bosm, “breast or inner part”; the verb is now rare and literary.',C('embosom.s1','文学描写','The village was embosomed in pine-covered hills, sheltered from the wind by the slopes that rose around it.','村庄被松树覆盖的山丘环抱，四周升起的坡地为它挡住了风。','The village / was embosomed in pine-covered hills / sheltered from the wind / by the slopes that rose around it.','embosom 是罕见文学动词，可表示环抱、包围，也可表示珍爱；此处为环绕义。','山坡从四面围住村庄，符合被环抱的 s1。'),'The valley was embosomed in mountains, standing completely outside and far from the surrounding slopes.','The valley was surrounded by mountains and sheltered by the surrounding slopes.','置于山中环绕与远离周围山坡互相矛盾。',[
Q('embosom',1,1,'A hamlet embosomed in hills is?','nestled among surrounding hills','located far beyond any hills','built on a ship’s mast','embosom 可描写地点被周围山丘环抱。'),Q('embosom',2,1,'In a literary sentence, to embosom someone may mean to?','cherish or hold closely','exclude from every form of care','measure the person’s height','该词也有怀抱、珍爱之义。'),Q('embosom',3,1,'Which setting best illustrates the “enclose” sense?','a cottage surrounded by woodland slopes','a cabin on a bare plain with no nearby rise','a desk inside an empty room only','四周树林坡地包围小屋，体现环抱义。'),Q('embosom',4,1,'Embosom is best described as?','a rare literary verb','a common unit of temperature','a standard name for a blood vessel','该动词罕见且偏文学。')]);
P('emboss','emboss came through French embosser, from en- plus bosse, “raised bump”; it describes a raised design pressed into a surface.',C('emboss.s1','印刷工艺','The printer embossed the invitation with a small gold border that readers could feel when they ran a finger across the card.','印刷工在请柬上压出了细细的金色凸边，读者用手指划过卡片时可以摸到。','The printer embossed the invitation / with a small gold border / that readers could feel / when they ran a finger across the card.','emboss 是及物动词，指压制或模压出凸起图案；它不同于向表面内刻下凹槽。','手指能摸到的凸起金边符合压印浮雕义 s1。'),'The printer embossed the card by cutting a deep groove below its surface.','The printer engraved the card by cutting a deep groove below its surface.','切出凹槽属于雕刻；emboss 是压出凸起图案。',[
Q('emboss',1,1,'To emboss a seal on paper is to?','press it into a raised design','cut a deep hollow groove','paint over the paper until it is flat','emboss 让图案凸起。'),Q('emboss',2,1,'Which result shows that leather was embossed?','A raised pattern can be felt on it.','A deep hole was drilled through it.','The leather dissolved in water.','可触摸的凸起图案是压印效果。'),Q('emboss',3,1,'Embossing differs from engraving because embossing usually?','raises a design above the surface','removes all lettering','uses sound instead of a surface','emboss 形成凸起，engrave 多切出凹线。'),Q('emboss',4,1,'A company may emboss its logo on?','a leather notebook cover','an invisible radio signal','a spoken conversation','皮革封面可压印凸起标志。')]);
P('embroider','embroider came through French broder, “decorate with needlework”; figuratively it also means adding invented story details.',C('embroider.s1','手工技艺','She embroidered a row of blue flowers along the tablecloth, using small stitches that remained neat after washing.','她沿桌布绣了一排蓝色小花，针脚细密，洗过后依然整齐。','She embroidered a row of blue flowers / along the tablecloth / using small stitches / that remained neat after washing.','embroider 可作及物动词，指用线在织物上绣出图案；故事添油加醋义为 s2。','线迹在桌布上构成花朵，体现刺绣义 s1。'),'She embroidered flowers on the cloth by removing all thread and leaving it blank.','She left the cloth plain by removing all thread and decoration.','不留线迹的空白布面不是绣花。',[
Q('embroider',1,1,'To embroider a shirt is to?','sew decorative patterns onto it','cut it into unrelated pieces','dye it without using thread','embroider 的字面义是用线刺绣。'),Q('embroider',2,2,'A witness embroidering an account is?','adding invented details to the story','removing all dramatic details','transcribing each word exactly','比喻义是叙事时加入编造细节。'),Q('embroider',3,1,'Which object could be embroidered?','a cloth napkin with stitched flowers','a glass bottle with no fabric','a stone wall by pouring water on it','布餐巾可用线绣花。'),Q('embroider',4,2,'Why might a listener question an embroidered tale?','Its narrator may have exaggerated or invented details.','It must be a word-for-word legal record.','It contains no description at all.','该比喻义暗示叙述可能添油加醋。')]);
P('embryo','embryo came through Latin from Greek embryon, “young one”; it names an early unborn organism and, figuratively, something undeveloped.',C('embryo.s1','生物学','At this early stage the embryo consists of rapidly dividing cells, and its organs have not yet developed.','在这一早期阶段，胚胎由快速分裂的细胞构成，器官尚未发育。','At this early stage / the embryo consists of rapidly dividing cells / and its organs / have not yet developed.','embryo 可指尚未发育成熟的胚胎；比喻“萌芽阶段”是 s2。','细胞分裂且器官未形成，是胚胎早期阶段特征，符合 s1。'),'The embryo was fully grown and had completed every stage of development before conception.','The embryo was at an early stage and had not completed development.','embryo 指早期未成熟阶段，不是受孕前已发育完成的个体。',[
Q('embryo',1,1,'In biology, an embryo is?','an organism at an early developmental stage','a fully grown adult animal','a fossil formed from stone only','embryo 指生物体早期发育阶段。'),Q('embryo',2,2,'An idea in embryo is?','a new idea that is not yet developed','a finished policy already in operation','an idea that has been forgotten','比喻义指尚处于初创阶段的事物。'),Q('embryo',3,1,'Which phrase uses the biological sense?','the embryo’s cells began to divide','the embryo of a business plan attracted investors','the embryo of the debate remained vague','细胞发育语境使用其生物义。'),Q('embryo',4,2,'A project described as “in embryo” is?','still at an early, undeveloped stage','already completed and archived','physically inside a human womb','短语比喻项目仍在萌芽阶段。')]);
P('embryological','embryological is formed from embryology plus -ical; embryology combines embryo with -logy, “study of.”',C('embryological.s1','医学研究','The embryological study compared early tissue samples to trace how the heart and limbs form during development.','这项胚胎学研究比较了早期组织样本，以追踪心脏和四肢在发育过程中如何形成。','The embryological study / compared early tissue samples / to trace how the heart and limbs form / during development.','embryological 作形容词，修饰研究、发育或证据等与胚胎学有关的名词。','研究追踪胚胎发育中器官形成，符合胚胎学相关义 s1。'),'The embryological report studied adult election campaigns and voting districts.','The political report studied adult election campaigns and voting districts.','选举竞选与选区属于政治研究，不涉及胚胎或发育。',[
Q('embryological',1,1,'Embryological research focuses on?','early development of an organism','the movement of planets','the design of road signs','胚胎学研究早期生物发育。'),Q('embryological',2,1,'Which phrase uses embryological correctly?','embryological development of the heart','embryological timetable for a train','embryological flavor of a soup','心脏在胚胎阶段的发育符合该形容词。'),Q('embryological',3,1,'An embryological sample is most likely taken from?','early developing tissue','a mature bridge support','a mineral fuel deposit','胚胎组织样本与早期发育相关。'),Q('embryological',4,1,'The suffix -ical here makes embryological?','an adjective describing a field-related matter','a verb meaning to give birth','a noun for a laboratory worker','embryological 是形容词。')]);
P('embryology','embryology combines embryo, from Greek embryon “young one,” and -logy, “study.”',C('embryology.s1','课程介绍','Embryology examines how an organism develops from its earliest stages, including the formation of tissues and organs.','胚胎学研究生物体如何从最早阶段发育，包括组织和器官的形成。','Embryology examines how an organism develops / from its earliest stages / including the formation / of tissues and organs.','embryology 是学科名词，指研究胚胎及其发育的科学。','早期发育以及组织器官形成是胚胎学核心研究对象，符合 s1。'),'The course in embryology focused exclusively on the long-term orbit of comets.','The course in astronomy focused on the long-term orbit of comets.','彗星轨道属于天文学，不是胚胎学。',[
Q('embryology',1,1,'Embryology is the study of?','embryos and their development','weather patterns over oceans','ancient writing systems','embryology 研究胚胎及其发育。'),Q('embryology',2,1,'A class in embryology might examine?','how organs form in early development','how rivers carve mountain valleys','how contracts are enforced','器官如何形成是胚胎学内容。'),Q('embryology',3,1,'Which specialist most likely uses embryology?','a developmental biologist','a tax auditor','a music conductor','发育生物学家会运用胚胎学。'),Q('embryology',4,1,'The ending -logy usually signals?','a field of study','a past-tense verb','a measure of distance','-logy 常表示学科或研究领域。')]);
P('embryonic','embryonic is formed from embryo plus -ic; embryo came through Latin from Greek embryon, “young one.”',C('embryonic.s2','项目规划','The city’s recycling scheme is still embryonic: only two districts are participating, and funding for expansion has not been approved.','这座城市的回收计划仍处于萌芽阶段：目前只有两个区参与，扩展资金也尚未获批。','The city’s recycling scheme / is still embryonic / only two districts are participating / and funding for expansion has not been approved.','embryonic 可作形容词比喻“尚在早期、未充分发展”；生物学义见 s1。','参与范围小、资金未定说明计划尚未成熟，符合比喻义 s2。'),'The embryonic program had operated citywide for decades and had reached its final form.','The mature program had operated citywide for decades and had reached its final form.','运行数十年且已成熟的计划不是处在萌芽阶段。',[
Q('embryonic',1,2,'An embryonic proposal is?','at a very early stage of development','fully tested and complete','legally impossible to change','比喻义表示仍处于初期、尚未成形。'),Q('embryonic',2,1,'An embryonic tissue sample is related to?','an embryo’s development','an adult’s retirement plan','a river’s water level','生物学形容词义指与胚胎有关。'),Q('embryonic',3,2,'Which project is embryonic?','a pilot idea with no settled plan or budget','a mature service used by millions for years','a finished report already archived','试点且计划资金未定说明项目尚在萌芽阶段。'),Q('embryonic',4,2,'In “the industry is embryonic,” embryonic means?','new and not yet fully developed','biologically inside a womb','old and declining','该词常比喻新兴、未充分发展的行业。')]);
P('emend','emend came from Latin emendare, “remove fault or correct,” from e- and menda “fault.”',C('emend.s1','校勘','The editor emended the damaged manuscript after comparing it with two reliable copies of the same passage.','编辑把受损手稿与另外两份可靠抄本对照后，校订了其中的错误。','The editor emended the damaged manuscript / after comparing it / with two reliable copies / of the same passage.','emend 是及物动词，常用于校勘或订正书面文本；不等于改写整体风格。','对照抄本后修正手稿中的错误，符合校勘义 s1。'),'The scholar emended the manuscript by adding several deliberate spelling errors.','The scholar corrupted the manuscript by adding several deliberate spelling errors.','添加错误会损坏文本，不是订正错误。',[
Q('emend',1,1,'To emend a manuscript is to?','correct errors in its text','translate it aloud without changing it','destroy every copy','emend 指校正书面文本中的错误。'),Q('emend',2,1,'An editor might emend a passage after?','comparing manuscript versions','painting the book cover','counting the library chairs','对照版本有助于校勘文本。'),Q('emend',3,1,'Which is an emendation?','changing a scribal error to the supported wording','adding an unsupported plot twist','moving a book to another shelf','订正抄写错误是校勘。'),Q('emend',4,1,'Emend is most at home in?','textual scholarship and editing','weather forecasting','sports coaching','emend 常用于文本校勘和编辑。')]);
P('emergence','emergence derives from emerge, from Latin emergere, “rise out or come forth.”',C('emergence.s1','科技发展','The emergence of low-cost solar panels changed the market by making home electricity generation practical for more families.','低成本太阳能板的出现改变了市场，使更多家庭能够实际利用住宅发电。','The emergence of low-cost solar panels / changed the market / by making home electricity generation practical / for more families.','emergence 是名词，表示出现、显现或开始变得重要。','低成本产品进入市场并带来影响，体现新事物出现的 s1。'),'The emergence of the new method meant it had disappeared before anyone could use it.','The disappearance of the old method meant it was no longer available.','出现与消失相反；新方法出现不等于它此前已消失。',[
Q('emergence',1,1,'The emergence of a new disease means the disease?','has appeared or become recognized','has been permanently cured','was never observed or reported','emergence 表示出现或开始被人们注意到。'),Q('emergence',2,1,'Which event illustrates the emergence of a leader?','A previously unknown organizer begins to gain influence.','A long-serving leader retires from public life.','A meeting ends without a decision.','新人物开始产生影响体现显现、崛起。'),Q('emergence',3,1,'“The emergence of digital maps” refers to their?','appearance and growing importance','physical destruction','translation into a different language','emergence 可指新技术出现并逐渐重要。'),Q('emergence',4,1,'Choose the opposite of emergence.','disappearance','arrival','development','disappearance 表示消失，与出现相反。')]);
P('emergent','emergent is from emerge, ultimately Latin emergere “rise out”; systems theory uses it for properties arising from a whole.',C('emergent.s2','复杂系统','The flock showed emergent behavior: no bird directed the turns, yet the group moved as if it were following one coordinated plan.','鸟群表现出涌现行为：没有一只鸟指挥转向，但整个群体仿佛遵循同一协调计划。','The flock showed emergent behavior / no bird directed the turns / yet the group moved / as if it were following one coordinated plan.','emergent 的系统义 s2 指整体互动产生、而非单一部分直接安排的性质；s1 指新近出现的。','协调模式从许多个体互动中产生，符合系统涌现义 s2。'),'The flock displayed emergent coordination because one trained bird gave every turn signal.','The flock displayed coordinated behavior because one trained bird gave every turn signal.','若单只鸟直接发出每个指令，不能说明群体性质由整体互动涌现。',[ 
Q('emergent',1,2,'An emergent pattern in a system?','arises from interactions among parts','is imposed in full by one isolated component','is always visible before the system exists','系统义强调整体互动产生新模式。'),Q('emergent',2,1,'An emergent technology is?','newly appearing or beginning to matter','extinct for centuries','unrelated to any recent change','新兴技术是刚出现或开始变得重要的技术。'),Q('emergent',3,2,'Which best illustrates emergent behavior?','many simple agents collectively create an unplanned pattern','a single controller dictates every movement','a machine remains switched off','整体模式由许多简单个体共同形成。'),Q('emergent',4,1,'The emergent sector of an economy is?','a sector that is newly developing','a sector that has vanished entirely','a sector with no participants','emergent 也可表示新兴、刚出现。')]);
P('emerging','emerging is the present participle of emerge, from Latin emergere, “rise out or come forth.”',C('emerging.s1','国际市场','The company is testing its payment app in three emerging markets where smartphone use is growing quickly.','该公司正在三个智能手机使用量迅速增长的新兴市场测试支付应用。','The company is testing its payment app / in three emerging markets / where smartphone use / is growing quickly.','emerging 常作前置形容词，描述新近发展、正在形成或崭露头角的事物。','市场正在快速发展而非已经消失，符合新兴义 s1。'),'The emerging market had stopped developing decades ago and no longer had any activity.','The declining market had stopped developing decades ago and no longer had any activity.','长期停止发展且失去活力的市场不宜称 emerging。',[
Q('emerging',1,1,'An emerging market is one that is?','developing and gaining economic importance','fully closed and inactive','only a market for old antiques','emerging market 指正在发展的新兴市场。'),Q('emerging',2,1,'An emerging writer is?','beginning to attract attention','unknown because no work exists','retired from writing','emerging 也形容崭露头角的人。'),Q('emerging',3,1,'Which phrase is natural?','an emerging field of research','an emerging ancient ruin that never changes','an emerging finished deadline','新兴研究领域正在发展形成。'),Q('emerging',4,1,'The word emerging emphasizes that something?','is beginning to appear or become prominent','has been fully established for centuries','has already disappeared','它强调开始出现或崭露头角。')]);
P('emeritus','emeritus comes from Latin emeritus, “having served one’s term,” from emereri, “serve out.”',C('emeritus.s1','大学职衔','After retiring from the department, Professor Lin retained the title professor emeritus and continued to advise graduate students.','林教授从院系退休后保留了荣誉退休教授头衔，并继续指导研究生。','After retiring from the department / Professor Lin retained the title / professor emeritus / and continued to advise graduate students.','emeritus 作名词或后置形容词，表示退休后保留荣誉头衔的职务；女性形式常见 emerita。','退休后仍保留教授称号，符合 s1。'),'The professor was named emeritus before beginning her first day in the job.','The professor was named assistant professor before beginning her first day in the job.','emeritus 指从职务退休后保留头衔，不能描述首次上任前。',[
Q('emeritus',1,1,'A professor emeritus is generally?','retired but retaining an academic title','a student who has not graduated','a temporary visiting schoolchild','emeritus 是退休后保留职衔的教授。'),Q('emeritus',2,1,'Which description fits an emeritus judge?','a retired judge who keeps the honorific title','a newly appointed court clerk','a judge currently on trial','该头衔强调已退休且保留称号。'),Q('emeritus',3,1,'Emeritus most commonly follows which kind of title?','professor','river','temperature','常见搭配是 professor emeritus。'),Q('emeritus',4,1,'The term emeritus implies that the person?','has retired from the post after serving','has just applied for the post','has never held the post','其含义含有已任职并退休。')]);
P('emigrant','emigrant combines Latin e- “out” with migrare “move”; it names a person viewed as leaving a country.',C('emigrant.s1','移民史','The emigrant left Ireland for Canada in search of work, writing to relatives about the difficult ocean crossing.','这名移民为寻找工作从爱尔兰迁往加拿大，并写信向亲属讲述艰难的海上旅程。','The emigrant left Ireland for Canada / in search of work / writing to relatives / about the difficult ocean crossing.','emigrant 是以离开原居国的视角称呼迁居海外的人；对目的地而言通常称 immigrant。','人物从爱尔兰离开并迁往加拿大，体现迁出视角 s1。'),'Viewed from the country she left, she was an emigrant arriving permanently from abroad.','Viewed from the country she left, she was an emigrant departing permanently for abroad.','emigrant 从原居国看是离境者，而不是从海外抵达者。',[
Q('emigrant',1,1,'An emigrant is someone who?','leaves a country to live elsewhere','visits a town for one afternoon','moves between rooms in one house','emigrant 指离开本国去别处定居的人。'),Q('emigrant',2,1,'From Ireland’s perspective, a person moving from Ireland to Canada is an?','emigrant','immigrant to Ireland','tourist who never departs','以爱尔兰为视角，此人离境，称 emigrant。'),Q('emigrant',3,1,'Which preposition pattern fits the source-country view?','an emigrant from Poland','an emigrant at a lunch table','an emigrant under a microscope','emigrant from 引出移出国家。'),Q('emigrant',4,1,'A person permanently leaving a country is its?','emigrant','resident who never moves','border official','从一国迁出者是该国的 emigrant。')]);
P('emigrate','emigrate combines Latin e- “out” with migrare “move”; it means leave one country to settle in another.',C('emigrate.s1','家庭迁徙','Her grandparents emigrated from Greece in the 1960s and settled near relatives who had already moved to Australia.','她的祖父母在20世纪60年代从希腊移居海外，定居在已迁往澳大利亚的亲属附近。','Her grandparents emigrated from Greece / in the 1960s / and settled near relatives / who had already moved to Australia.','emigrate 通常与 from 连用，强调离开原籍国；immigrate to 则从目的地角度说迁入。','祖父母离开希腊并在海外定居，介词 from 标明迁出视角 s1。'),'They emigrated to Greece from Australia, meaning they left Greece and settled in Australia.','They immigrated to Greece from Australia, meaning they left Australia and settled in Greece.','emigrate from + 原籍；前往目的地用 immigrate to，原句方向释义冲突。',[ 
Q('emigrate',1,1,'Choose the correct phrase for leaving Spain to settle abroad.','emigrate from Spain','emigrate Spain to','emigrate at Spain','emigrate from 引出离开的国家。'),Q('emigrate',2,1,'The verb emigrate focuses on?','departure from a home country','arrival at a destination only','a short holiday abroad','emigrate 是从原居国迁出的视角。'),Q('emigrate',3,1,'A family moving permanently out of Peru will?','emigrate from Peru','immigrate from Peru into Peru','emigrate the Peruvian weather','迁出秘鲁用 emigrate from Peru。'),Q('emigrate',4,1,'Which sentence uses emigrate correctly?','They emigrated from Nepal to start a new life abroad.','They emigrated Nepal without a preposition.','They emigrated to Nepal, meaning they left Nepal.','emigrate from Nepal 表示离开尼泊尔。')],'preposition');
P('eminence','eminence comes from Latin eminentia, “prominence,” from eminere “stand out”; it can also denote a raised place.',C('eminence.s1','学术声望','Her eminence in climate science came from decades of careful fieldwork and a series of studies that other researchers relied on.','她在气候科学领域的卓越声望来自数十年的细致野外工作，以及其他研究者赖以参考的一系列研究。','Her eminence in climate science / came from decades of careful fieldwork / and a series of studies / that other researchers relied on.','eminence 可指卓越地位或声望；地貌中的高地义为 s2。','长期受同行重视的研究使她声名卓著，符合 s1。'),'Her eminence in the field meant nobody had heard of her work and she had no influence.','Her obscurity in the field meant nobody had heard of her work and she had no influence.','无人知晓且没有影响表示默默无闻，不是 eminence。',[
Q('eminence',1,1,'A scientist’s eminence refers to the scientist’s?','high standing or distinction','lack of any recognition','physical height only','eminence 可指声望卓著或地位显赫。'),Q('eminence',2,2,'A hiker climbed an eminence to see over the valley. The eminence is?','a raised piece of ground','a deep underwater trench','a flat sheet of paper','地貌义 eminence 指隆起的高地。'),Q('eminence',3,1,'A person of eminence is generally?','widely respected in a field','unknown and ignored by everyone','new to the alphabet','显赫者通常在领域内受尊敬。'),Q('eminence',4,1,'Which phrase uses the reputation sense?','a scholar of great eminence','an eminence above the riverbank','the eminence of a hilltop trail','scholar of great eminence 指卓越学者。')]);
P('emolument','emolument came from Latin emolumentum, originally a miller’s fee and later compensation or profit from office.',C('emolument.s1','公共职位','The disclosure listed the judge’s salary, housing allowance, and other emoluments received for holding public office.','申报列出了法官因担任公职而获得的薪水、住房补贴和其他报酬。','The disclosure listed the judge’s salary / housing allowance / and other emoluments / received for holding public office.','emolument 是较正式的名词，指薪资、津贴或任职所得收益。','工资与住房津贴均为因任职而得的报酬，符合 s1。'),'The official reported no emoluments despite receiving a salary and housing allowance for the post.','The official reported emoluments, including the salary and housing allowance for the post.','职位工资和津贴都属于 emoluments，不能说没有任何报酬。',[
Q('emolument',1,1,'An emolument is?','compensation or benefit received for work or office','a penalty paid for breaking a law','a piece of office furniture','emolument 指薪水、津贴或任职收益。'),Q('emolument',2,1,'Which item is an emolument of public office?','an official housing allowance','a private holiday unrelated to the job','a weather forecast','职位提供的住房津贴是任职所得。'),Q('emolument',3,1,'The word emolument is most likely in?','a formal disclosure of an official’s compensation','a casual recipe for soup','a children’s rhyme about toys','该词较正式，常见于报酬或公职语境。'),Q('emolument',4,1,'Salary and benefits from holding office are?','emoluments','emergences','embryos','职位报酬可统称 emoluments。')]);
P('emotional','emotional is formed from emotion plus -al; emotion entered English through French from Latin emovere, “move out or stir.”',C('emotional.s2','毕业典礼','The speaker became emotional while thanking her parents, pausing several times as tears came to her eyes.','演讲者在感谢父母时情绪激动，眼中含泪，几次停下来。','The speaker became emotional / while thanking her parents / pausing several times / as tears came to her eyes.','emotional 可指“与情感有关”s1，也可指表现强烈感情、容易激动的 s2。','流泪停顿显示强烈情绪表现，符合 s2。'),'He remained emotional and showed no feeling at all when hearing the news.','He remained calm and showed no feeling when hearing the news.','毫无情绪表现对应 calm，而不符合情绪激动的 emotional。',[
Q('emotional',1,2,'Someone who becomes emotional at a farewell may?','cry or show strong feelings','remain entirely unmoved','calculate a distance','该义强调显露强烈感情。'),Q('emotional',2,1,'An emotional issue is one that?','relates to people’s feelings','concerns only a machine’s voltage','has no human significance','s1 指与情绪、感情相关。'),Q('emotional',3,2,'Which scene is most emotional?','A parent weeps during a child’s farewell.','A clerk checks a neutral invoice.','A thermometer records room temperature.','落泪体现强烈情绪。'),Q('emotional',4,1,'“Emotional support” mainly concerns?','help with a person’s feelings and mental well-being','repair of an engine','payment of a tax bill','该搭配指情绪层面的支持。')]);
P('emotionally','emotionally is formed from emotional plus -ly and means with regard to feelings or in a visibly strong-feeling manner.',C('emotionally.s1','康复','After the accident, he was physically healed but still emotionally affected by the loss of his friend.','事故后，他的身体已经康复，但仍在情感上受到朋友离世的影响。','After the accident / he was physically healed / but still emotionally affected / by the loss of his friend.','emotionally 可指就情感方面而言 s1，也可指表现强烈情绪地 s2。','身体康复与情感仍受影响形成对照，符合情感方面的 s1。'),'She was emotionally exhausted, meaning only her bank account had run out of money.','She was financially exhausted, meaning her bank account had run out of money.','账户资金耗尽是 financially，不是情感上疲惫。',[
Q('emotionally',1,1,'If someone is emotionally affected by grief, the grief affects?','their feelings','the engine’s fuel supply','the room’s temperature','emotionally 描述情感方面受到影响。'),Q('emotionally',2,2,'She spoke emotionally at the reunion, so she?','showed strong feelings while speaking','read a completely neutral meter','remained silent throughout','s2 表示说话时表现出强烈感情。'),Q('emotionally',3,1,'“Emotionally secure” most directly means secure in?','one’s feelings and relationships','one’s bank balance only','one’s physical address','该表达涉及感情上的安全感。'),Q('emotionally',4,2,'Which use means “with visible feeling”?','He emotionally described the reunion.','He emotionally balanced the budget without reaction.','He emotionally measured the table’s length.','此句把 emotionally 用作表现强烈感情地。')]);
P('emotive','emotive comes from emotion plus -ive, through French/Latin roots meaning “to move”; it describes language that evokes feeling.',C('emotive.s1','公共讨论','The phrase “children left without shelter” is emotive, because it is chosen to stir concern rather than merely report a number.','“儿童无处栖身”这句话带有煽情色彩，因为它旨在激起关切，而不只是报告数字。','The phrase “children left without shelter” / is emotive / because it is chosen to stir concern / rather than merely report a number.','emotive 通常形容引发强烈感情的措辞、话题或表达；emotional 更常表示与情感有关或情绪激动。','该措辞意在唤起关切，体现引发情绪的 s1。'),'The report used emotive language to remain entirely neutral and stir no reaction.','The report used neutral language to avoid stirring a reaction.','引发情绪的 emotive 用语与完全中性、不引起反应矛盾。',[
Q('emotive',1,1,'An emotive phrase is designed to?','arouse a strong feeling','remove all emotional effect','give an exact temperature','emotive 指能够激起感情的。'),Q('emotive',2,1,'Which headline is more likely emotive?','“Families Face a Winter Without Heat”','“Heating Use Rises by Two Percent”','“Report Published on Tuesday”','面临寒冬无暖气更容易激起读者情绪。'),Q('emotive',3,1,'An emotive topic tends to?','provoke strong reactions','have no emotional significance','be a synonym for a number','emotive 话题容易引发强烈反应。'),Q('emotive',4,1,'A writer choosing emotive wording may want to?','persuade by appealing to readers’ feelings','avoid influencing any response','list data in a purely mathematical table','情绪化措辞常借感情影响读者。')]);
P('empathy','empathy was coined from Greek empatheia, “passion,” using en- “in” and pathos “feeling.”',C('empathy.s1','护理沟通','The nurse showed empathy by listening without interruption and acknowledging how frightening the diagnosis felt to the patient.','护士专心倾听并理解病人面对诊断时的恐惧，表现出了共情。','The nurse showed empathy / by listening without interruption / and acknowledging / how frightening the diagnosis felt to the patient.','empathy 指理解并体会他人感受，常与 for 或 with 搭配；不等同于替别人解决问题。','倾听并承认病人的恐惧显示理解其感受，符合 s1。'),'The counselor showed empathy by mocking the client’s fear and refusing to hear about it.','The counselor showed contempt by mocking the client’s fear and refusing to hear about it.','嘲笑并拒绝倾听表现出轻蔑，不是对感受的理解。',[
Q('empathy',1,1,'To show empathy is to?','understand another person’s feelings','dismiss the person’s feelings as irrelevant','copy the person’s handwriting','empathy 是理解他人的感受。'),Q('empathy',2,1,'Which response shows empathy?','“That sounds painful; I’m listening.”','“Your concern is ridiculous; stop talking.”','“I will change the subject immediately.”','承认痛苦并倾听体现共情。'),Q('empathy',3,1,'Empathy differs from simply giving advice because empathy first?','recognizes and understands the other person’s perspective','orders the person to obey','judges the person without listening','共情首先理解对方的感受与视角。'),Q('empathy',4,1,'A character who understands a stranger’s grief displays?','empathy','envy','indifference','理解陌生人的悲伤体现 empathy。')]);
P('emphatic','emphatic derives from Greek emphatikos, “expressive,” through emphasis; it describes stress or forceful certainty.',C('emphatic.s1','会议发言','The chair gave an emphatic refusal, stating firmly that the unsafe proposal would not be approved under any circumstances.','主席断然拒绝，并坚定表示无论如何都不会批准这项不安全的提案。','The chair gave an emphatic refusal / stating firmly / that the unsafe proposal would not be approved / under any circumstances.','emphatic 常修饰 denial、refusal、support 等，表示强调有力或态度坚决。','firmly 与 under any circumstances 显示坚决强调，符合 s1。'),'She gave an emphatic refusal by murmuring “perhaps” without expressing any firm view.','She gave a hesitant response by murmuring “perhaps” without expressing any firm view.','含糊迟疑的 perhaps 不是有力、坚决的拒绝。',[
Q('emphatic',1,1,'An emphatic denial is?','a forceful, definite denial','a quiet uncertainty','a question with no answer','emphatic 表示强调有力、态度明确。'),Q('emphatic',2,1,'Which reply sounds emphatic?','“Absolutely not; I will not sign.”','“I am not quite sure, perhaps later.”','“What time does the shop close?”','明确而坚决地拒绝语气 emphatic。'),Q('emphatic',3,1,'An emphatic stress in speech is?','strongly marked emphasis','a pause caused by silence only','a spelling change in writing','emphatic 也指语音或表达上的强烈强调。'),Q('emphatic',4,1,'Choose the natural collocation.','an emphatic victory','an emphatic temperature','an emphatic window width','emphatic victory 表示优势显著、结果明确的胜利。')]);
P('empiricism','empiricism is formed from empiric plus -ism; empiric ultimately comes from Greek empeiria, “experience.”',C('empiricism.s1','哲学课堂','Empiricism holds that knowledge depends on observation and experience, so the class compared claims with evidence gathered through the senses.','经验论认为知识依赖观察和经验，因此课堂把各种主张与通过感官获得的证据作比较。','Empiricism holds that knowledge depends on observation and experience / so the class compared claims / with evidence gathered through the senses.','empiricism 是哲学立场名词，强调经验与观察在知识形成中的作用。','以感官观察所得证据检验主张，体现经验论 s1。'),'The empiricism course taught that knowledge comes only from unsupported guesses with no observation.','The empiricism course taught that knowledge is grounded in observation and experience.','拒绝任何观察证据与经验论的核心主张相反。',[
Q('empiricism',1,1,'Empiricism emphasizes knowledge gained through?','observation and experience','unsupported authority alone','dreams with no evidence','经验论重视观察和经验。'),Q('empiricism',2,1,'An empiricist is most likely to ask for?','evidence gathered from experience','a claim accepted without examination','a prediction based only on title','经验论者倾向要求经验观察证据。'),Q('empiricism',3,1,'Which statement fits empiricism?','Test the claim against observable evidence.','Accept it because it cannot be checked.','Reject every sensory observation automatically.','以可观察证据检验主张符合经验论。'),Q('empiricism',4,1,'The root idea behind empiricism is?','experience','emperor','embroidery','empiricism 源自表示经验的词根。')]);
P('employe','employe is a variant spelling of employee, from employ plus the person suffix -ee; the spelling is uncommon in modern English.',C('employe.s1','旧式档案','One archival notice spelled the worker “employe,” an uncommon variant of employee, while later company records used the standard spelling.','一份旧档案把工人写作 employe，这是 employee 的罕见拼法；后来的公司记录使用标准拼法。','One archival notice / spelled the worker “employe” / an uncommon variant of employee / while later company records used the standard spelling.','employe 是少见变体拼写，通常写 employee；意为受雇工作的人。','档案中特意说明其为 employee 的罕见拼法，体现 s1。'),'The modern report described a paid worker as an employe, the standard spelling used everywhere today.','The modern report described a paid worker as an employee, the standard modern spelling.','现代通用标准拼法是 employee；employe 属罕见拼写变体。',[ 
Q('employe',1,1,'Employe is best treated as?','an uncommon spelling variant of employee','the only accepted modern spelling','a verb meaning to dismiss','employe 是 employee 的罕见变体。'),Q('employe',2,1,'An employe is a person who?','is hired and paid to work','owns the entire company by definition','visits the office once as a tourist','该词指受雇工作的人。'),Q('employe',3,1,'Which spelling is standard in present-day general English?','employee','employe','employeer','employee 是当代标准拼法。'),Q('employe',4,1,'In an old document, employe probably refers to?','an employee','an employer only','a workplace building','旧文档中该变体仍指雇员。')],'spelling');
P('employee','employee is formed from employ plus -ee, a suffix often marking the person receiving an action or role.',C('employee.s1','劳动合同','Each employee received a written contract explaining the hours, salary, and leave available during the first year.','每位员工都收到一份书面合同，说明第一年的工时、薪资和休假安排。','Each employee received a written contract / explaining the hours, salary, and leave / available during the first year.','employee 作可数名词指受雇为雇主工作的个人；员工群体义见 s2。','每个人分别收到合同，指一名受雇者，符合 s1。'),'The employee hired staff and paid their wages, while the company owner received orders from that worker.','The employer hired staff and paid their wages, while the employee received orders from the company.','雇佣并发工资通常是 employer 的职责，不应与 employee 倒置。',[ 
Q('employee',1,1,'An employee is someone who?','works for an employer','owns every business by definition','purchases a service once','employee 是为雇主工作的雇员。'),Q('employee',2,2,'“The employees voted together” refers to?','the workers as a group','one individual worker only','the company’s customers','复数 employees 在此表示员工群体。'),Q('employee',3,1,'Which item might an employee receive?','a work contract','a tax imposed on a city','a license to employ the company','员工可能收到工作合同。'),Q('employee',4,1,'A person paid by a shop to serve customers is the shop’s?','employee','employer in every case','customer only','被商店雇来服务顾客的人是员工。')],'confusable');
P('empower','empower combines em- “put into” with power, from Old French poeir; it means give authority, ability, or confidence.',C('empower.s1','社区治理','The new policy empowered neighborhood councils to approve small accessibility projects without waiting for a citywide vote.','新政策授权社区委员会批准小型无障碍项目，不必等待全市投票。','The new policy / empowered neighborhood councils / to approve small accessibility projects / without waiting for a citywide vote.','empower 常用 empower someone to do something，表示赋予权力、能力或信心。','委员会获得批准项目的权限，体现授权义 s1。'),'The policy empowered the council by forbidding it from making any decisions.','The policy restricted the council by forbidding it from making any decisions.','禁止作决定是限制权力，不是赋权。',[
Q('empower',1,1,'To empower a local council is to?','give it authority or ability to act','remove every power it has','replace it with a weather station','empower 表示赋予权力或能力。'),Q('empower',2,1,'Which sentence uses empower correctly?','The training empowered nurses to lead the review.','The training empowered nurses from leading any review.','The training empowered the review by deleting it.','empower sb to do sth 是自然结构。'),Q('empower',3,1,'A mentor empowers a student by?','building the student’s confidence and capacity','preventing the student from learning','hiding all useful information','赋予能力也可指建立信心和行动力。'),Q('empower',4,1,'The law empowered residents to appeal, meaning it?','gave residents the right to appeal','made appeals impossible','required residents to leave town','法律赋予居民上诉权。')]);
P('empress','empress is formed from emperor with the feminine suffix -ess; emperor came through Old French from Latin imperator.',C('empress.s1','王室史','The empress addressed the court after the succession ceremony, speaking as the female ruler of the empire rather than as a visiting guest.','继位仪式后，女皇向宫廷发表讲话；她是帝国的女性统治者，而非来访宾客。','The empress addressed the court / after the succession ceremony / speaking as the female ruler / of the empire rather than as a visiting guest.','empress 可指女性帝国统治者，也可指皇帝的妻子，须依语境判断。','继位并以统治者身份讲话，明确对应女性君主义 s1。'),'The empress was the male ruler who inherited the throne from his father.','The emperor was the male ruler who inherited the throne from his father.','男性帝国统治者称 emperor，empress 是女性统治者或皇帝妻子。',[ 
Q('empress',1,1,'An empress may be?','a female ruler of an empire','the male ruler of every empire','a member of parliament by definition','empress 可指帝国女皇。'),Q('empress',2,1,'The word empress can also refer to?','the wife of an emperor','the emperor’s horse','a palace servant only','它也可指皇帝的妻子。'),Q('empress',3,1,'Which title is the usual masculine counterpart of empress?','emperor','princess','duchess','emperor 是男性对应称谓。'),Q('empress',4,1,'A woman who rules an empire in her own right is an?','empress','emperor','emigrant','女性帝国统治者可称 empress。')],'word-formation');
P('emulation','emulation is formed from emulate plus -ion; emulate comes from Latin aemulari, “strive to equal or surpass.”',C('emulation.s1','科学竞赛','Her emulation of the award-winning laboratory’s methods pushed her team to reproduce the results and then improve the measurement process.','她效仿获奖实验室的方法，带领团队复现结果并进一步改进测量流程。','Her emulation of the award-winning laboratory’s methods / pushed her team / to reproduce the results / and then improve the measurement process.','emulation 可指仿效他人努力达到或超过其成就，也可指模仿某系统的过程。','团队以复现并改进先进方法为目标，体现仿效竞争义 s1。'),'Her emulation of the laboratory meant she refused to study its methods or compare results.','Her rejection of the laboratory’s methods meant she refused to study them or compare results.','拒绝学习和比较不是仿效。',[
Q('emulation',1,1,'Emulation of a successful team means?','trying to match or surpass its achievement','preventing it from entering a contest','copying its name without learning anything','emulation 指努力仿效并争取达到或超过。'),Q('emulation',2,1,'A student studies a prize-winning design and builds a better one. This is?','emulation','abandonment','emigration','学习并争取改进是仿效竞争。'),Q('emulation',3,1,'In computing, software emulation may let one system?','imitate another system’s behavior','erase all other programs','measure a person’s salary','技术义也指模拟另一系统的运行方式。'),Q('emulation',4,1,'Which is the closest paraphrase of emulation?','ambitious imitation','complete indifference','accidental damage','ambitious imitation 表示带有追赶目标的仿效。')]);
P('emulsion','emulsion derives from Latin emulgere, “milk out”; it names a mixture in which one liquid is dispersed through another immiscible liquid.',C('emulsion.s1','食品科学','The dressing remained an emulsion after shaking, with tiny oil droplets suspended evenly through the vinegar instead of separating at once.','摇匀后，这种调味汁保持为乳状液，细小油滴均匀分散在醋中，没有立即分层。','The dressing remained an emulsion after shaking / with tiny oil droplets suspended evenly through the vinegar / instead of separating at once.','emulsion 是一种液体微滴分散在另一种不相溶液体中的混合物；mayonnaise 是常见例子。','油滴分散在水相醋液中，符合乳状液义 s1。'),'The oil and vinegar formed a stable emulsion because they instantly separated into two untouched layers.','The oil and vinegar formed two layers because they separated instead of making an emulsion.','立即分层表示没有形成稳定乳状液。',[
Q('emulsion',1,1,'An emulsion contains?','small droplets of one liquid dispersed in another','a solid dissolved completely in a gas','two metals fused into one bar','乳状液由一种液体微滴分散于另一液体中。'),Q('emulsion',2,1,'Mayonnaise is commonly described as an?','emulsion of oil and water-based ingredients','emulsion of dry sand and iron','emulsion of two solid rocks','蛋黄酱的油相分散于水相，属于乳状液。'),Q('emulsion',3,1,'A mixture that separates immediately into clear oil and water layers is?','not a stable emulsion','a perfect permanent emulsion','a gas solution','立即分层说明液滴分散状态不稳定。'),Q('emulsion',4,1,'In an emulsion, the dispersed phase is present as?','tiny droplets','large dry sheets','sound waves','分散相以细小液滴形式存在。')]);
P('enamel','enamel came through Old French from Latin smaltum, related to a glassy coating; it can name the coating or the act of applying it.',C('enamel.s1','工艺品','The artisan fired the copper pendant until its blue enamel hardened into a smooth, glass-like surface.','工匠加热铜坠饰，直到蓝色珐琅釉烧结成光滑的玻璃状表面。','The artisan fired the copper pendant / until its blue enamel hardened / into a smooth, glass-like surface.','enamel 作名词指熔融后附着于金属、玻璃或陶器上的玻璃质彩釉；动词义见 s2。','加热后形成光滑玻璃质彩色涂层，符合名词义 s1。'),'The jeweller called the rough uncoated copper surface enamel even though no glassy layer had been applied.','The jeweller called the rough uncoated copper surface bare metal because no glassy layer had been applied.','没有涂覆玻璃质釉层的裸铜不是 enamel。',[
Q('enamel',1,1,'Decorative enamel on metal is usually?','a glass-like coating fused to the surface','a loose pile of dry leaves','a layer of untreated soil','珐琅釉是烧结在表面的玻璃质涂层。'),Q('enamel',2,2,'To enamel a bowl is to?','coat it with enamel','remove every coating from it','measure its volume','enamel 作动词指给表面涂釉。'),Q('enamel',3,1,'Which object most clearly has enamel?','a metal brooch with a fired colored glassy layer','an unpainted wooden spoon','a paper label on a box','金属饰品上的烧结彩釉符合名词义。'),Q('enamel',4,1,'Dental enamel is the?','hard outer covering of a tooth','soft tissue inside a muscle','liquid in the stomach','牙釉质是牙齿坚硬的外层。')]);
P('encapsulate','encapsulate is formed from capsule with en-; capsule traces to Latin capsula, “small box,” and the verb also means summarize in compact form.',C('encapsulate.s1','摘要写作','The final sentence encapsulates the report’s main finding: reliable transit depends on frequent service, not merely new stations.','最后一句概括了报告的主要发现：可靠的公共交通依赖高频服务，而不只是新车站。','The final sentence / encapsulates the report’s main finding / reliable transit depends on frequent service / not merely new stations.','encapsulate 可表示用简短形式概括要点；物理装入胶囊或封装是 s2。','一句话浓缩报告的核心结论，符合概括义 s1。'),'The final sentence encapsulated the report by repeating every paragraph word for word.','The final sentence summarized the report by stating its central finding briefly.','逐字重抄全部内容并非简明概括。',[
Q('encapsulate',1,1,'A sentence that encapsulates an argument?','expresses its central point briefly','reproduces every page in full','removes all mention of the argument','encapsulate 的抽象义是简要概括核心内容。'),Q('encapsulate',2,2,'To encapsulate a medicine is to?','enclose it in a capsule or protective shell','summarize its history in a paragraph','dissolve its container before packaging','物理义表示装入胶囊或密封外壳。'),Q('encapsulate',3,1,'Which best encapsulates a long report?','one concise sentence stating its main conclusion','a second full copy of every chapter','a list of unrelated page numbers','概括应简洁抓住报告结论。'),Q('encapsulate',4,1,'“This scene encapsulates the novel” means it?','captures the novel’s key idea in a compact example','physically stores the whole novel','changes the novel’s spelling','场景可浓缩体现作品核心思想。')]);
P('encase','encase combines en- with case, from Latin capsa, “box”; it means surround or cover something completely.',C('encase.s1','防护包装','Technicians encased the fragile sensor in foam and a sealed metal housing before shipping it across the country.','技术人员先用泡沫和密封金属外壳包住易碎传感器，再将它运往外地。','Technicians encased the fragile sensor / in foam and a sealed metal housing / before shipping it / across the country.','encase 常用 encase A in B，表示用某种材料或容器从四周包住 A。','泡沫与金属壳从外部包围传感器，符合 s1。'),'They encased the sensor in an open shelf, leaving every side completely uncovered.','They placed the sensor on an open shelf, leaving every side uncovered.','开放搁板不会从四周包裹传感器。',[
Q('encase',1,1,'To encase an object in glass is to?','surround it completely with glass','engrave a picture into the glass only','leave it exposed in open air','encase 表示将物体包在某材料中。'),Q('encase',2,1,'Which is naturally encased in a protective shell?','a delicate instrument sealed inside a case','an uncovered stone lying on a road','a sound heard across a room','密封外壳将仪器包覆起来。'),Q('encase',3,1,'Choose the common pattern.','encase the cable in insulation','encase the cable from insulation','encase in the cable insulation it','常见结构为 encase A in B。'),Q('encase',4,1,'Concrete can encase a steel support, meaning it?','surrounds and covers the support','removes the support from the structure','measures the support’s temperature','混凝土包围并覆盖钢支撑。')]);
P('enchant','enchant comes from Old French enchanter and Latin incantare, “to utter a spell”; modern use also means delight greatly.',C('enchant.s1','博物馆参观','The guide enchanted the children with a story about the moonstone, and they stayed after closing to hear how the tale ended.','导游用月光石的故事迷住了孩子们，闭馆后他们还留下来听故事结局。','The guide enchanted the children / with a story about the moonstone / and they stayed after closing / to hear how the tale ended.','enchant 是及物动词，表示强烈吸引并使人愉悦；可用 enchant someone with something。','孩子们被故事吸引到闭馆仍想继续听，体现使着迷义 s1。'),'The dull lecture enchanted the audience by making everyone lose interest and leave.','The dull lecture bored the audience, making everyone lose interest and leave.','听众失去兴趣并离场是厌倦，不是被迷住。',[
Q('enchant',1,1,'To enchant an audience is to?','delight and captivate it','bore it until everyone leaves','confuse it with an unreadable bill','enchant 表示使人着迷并愉悦。'),Q('enchant',2,1,'Which scene shows a child enchanted by a story?','The child begs to hear the next chapter.','The child closes the book and forgets it.','The child cannot see the page.','渴望继续听故事说明被吸引。'),Q('enchant',3,1,'A singer enchanted the crowd with her voice. The crowd was?','strongly charmed by the voice','ordered to leave the room','physically enclosed in a box','该动词指声音令听众着迷。'),Q('enchant',4,1,'Choose a natural object of enchant.','enchant visitors','enchant a distance into metres','enchant a receipt from tax','人可以被景色或表演迷住。')]);
P('enclosed','enclosed is the past participle of enclose, from en- plus close; it can mean included with a letter or surrounded by a barrier.',C('enclosed.s1','商务信函','Please find enclosed the signed form and a prepaid envelope for returning the completed application.','随信附上已签署的表格和一个预付邮资的信封，供寄回填好的申请表。','Please find enclosed / the signed form and a prepaid envelope / for returning / the completed application.','enclosed 作信函用语时表示随信附上的；被墙或围栏围起来是 s2。','表格和回邮信封一并放入信件，符合附上义 s1。'),'The letter stated that a form was enclosed, but the envelope contained no form or attachment.','The letter stated that a form was enclosed, and the envelope contained the attached form.','信里说已附上而信封实际空无附件，信息不一致。',[
Q('enclosed',1,1,'A document enclosed with a letter is?','included inside the same envelope','posted to the sender next year','printed only on the envelope exterior','enclosed 可指随信附上的材料。'),Q('enclosed',2,2,'A garden enclosed by a wall is?','surrounded by a barrier','attached inside an envelope','open on every side without a boundary','被墙环绕的花园符合围起来义 s2。'),Q('enclosed',3,1,'“Please find enclosed my receipt” means?','the receipt is included with the letter','the receipt is locked outside the building','the receipt has been destroyed','正式信函中 enclosed 表示随信附上。'),Q('enclosed',4,2,'Which place is enclosed?','a courtyard surrounded by a fence','a receipt included with a letter','an open plain without boundaries','围栏包围庭院，符合 s2。')]);
P('encompass','encompass came through Anglo-French from en- plus compasser, “measure or encircle”; it means include within a whole or surround.',C('encompass.s1','课程设计','The degree encompasses field research, data analysis, and a supervised placement, giving students experience in several parts of the profession.','这个学位课程涵盖实地研究、数据分析和带教实习，让学生接触该职业的多个方面。','The degree encompasses field research / data analysis / and a supervised placement / giving students experience in several parts of the profession.','encompass 可表示一个整体包含多个部分；环绕某地点是 s2。','多项学习内容均纳入学位课程，符合包含、涵盖义 s1。'),'The degree encompassed only laboratory work, while its official plan excluded every other subject.','The degree focused only on laboratory work, while its official plan excluded every other subject.','明确排除其他科目就不可能同时涵盖这些内容。',[
Q('encompass',1,1,'A course that encompasses history and science?','includes both subjects','excludes both subjects','takes place only outside the school','encompass 表示将多项内容纳入整体。'),Q('encompass',2,2,'A fence encompasses a field when it?','forms a boundary around the field','lists topics taught in the field','lies entirely outside the property','围栏环绕土地对应 s2。'),Q('encompass',3,1,'Which sentence uses the “include” sense?','The survey encompasses residents from every district.','The hills encompass the village on three sides.','A wall encompasses the garden physically.','调查纳入各区居民，使用包含义。'),Q('encompass',4,1,'A broad research project may encompass?','several related questions and methods','one unrelated lunch order only','no topics at all','项目可涵盖多个相关问题和方法。')]);
P('encouragement','encouragement is formed from encourage plus -ment; encourage came through French from Latin cor, “heart.”',C('encouragement.s1','团队辅导','The coach’s encouragement helped the novice return to practice after the first difficult competition.','教练的鼓励帮助新手在第一次艰难的比赛后重新回到训练中。','The coach’s encouragement / helped the novice return to practice / after the first difficult competition.','encouragement 指能增强信心的支持、赞扬或鼓舞，可作不可数名词，也可指一项鼓励的话。','鼓励让新手有信心重返训练，符合 s1。'),'Her encouragement discouraged the beginner and made her give up practice.','Her criticism discouraged the beginner and made her give up practice.','导致放弃练习的是打击而非鼓励。',[
Q('encouragement',1,1,'Encouragement from a teacher may help a learner?','feel confident enough to continue','forget every lesson immediately','avoid all future practice','鼓励可增强信心并帮助继续努力。'),Q('encouragement',2,1,'Which is an example of encouragement?','“You have improved; keep going.”','“You will never learn this.”','“Do not try again.”','肯定进步并支持坚持是鼓励。'),Q('encouragement',3,1,'A little encouragement can provide?','support and hope','a legal punishment','a technical measurement','encouragement 常指支持或让人有希望的话。'),Q('encouragement',4,1,'The crowd’s encouragement caused the runner to?','keep going despite fatigue','stop before the race began','change the weather','观众的鼓励促使跑者坚持。')]);
P('encroachment','encroachment is formed from encroach plus -ment; encroach came through French from a verb meaning seize or intrude upon.',C('encroachment.s1','土地边界','Neighbors documented the gradual encroachment of a new fence onto their garden, measuring each disputed section before speaking with the owner.','邻居记录新围栏逐步侵占花园的情况，并在与业主交涉前测量每处争议地段。','Neighbors documented the gradual encroachment / of a new fence onto their garden / measuring each disputed section / before speaking with the owner.','encroachment 是名词，指逐渐越过正当边界、侵犯土地或权利；常接 on/upon。','围栏逐渐越界到他人花园，体现 s1。'),'The neighbors called the fence encroachment because it stood entirely within the owner’s boundary and moved nowhere.','The neighbors called the fence correctly placed because it stood within the owner’s boundary.','围栏完全在业主边界内且未越界，不构成侵占。',[
Q('encroachment',1,1,'Encroachment on private land means?','gradual intrusion beyond proper boundaries','a fence repaired wholly on its owner’s land','a land survey that changes no boundary','encroachment 指逐渐侵入他人土地或权利范围。'),Q('encroachment',2,1,'A town objects to encroachment on residents’ privacy. It objects to?','an intrusion into their private lives','a public celebration in the square','a new library opening','侵犯隐私是权利边界被越过。'),Q('encroachment',3,1,'Which phrase is natural?','encroachment on local rights','encroachment at a sandwich','encroachment by the calendar date','常见搭配 encroachment on/upon。'),Q('encroachment',4,1,'An encroachment is often?','a gradual advance into another’s domain','a sudden legal transfer made with consent','a harmless weather forecast','该词强调越过界限的渐进侵入。')]);
P('encrust','encrust combines en- with crust, from Latin crusta, “hard covering”; it can form a crust or cover something with jewels.',C('encrust.s1','海岸岩石','After years of spray and salt, mineral deposits encrusted the rock ledge until its surface looked rough and pale.','经过多年海浪飞沫和盐分作用，矿物沉积物在岩架上结成硬壳，使表面显得粗糙发白。','After years of spray and salt / mineral deposits encrusted the rock ledge / until its surface looked rough and pale.','encrust 可作及物动词，指形成硬壳或用某物厚厚覆盖；也可表示镶满宝石。','沉积物在岩石上形成粗糙硬壳，符合 s1。'),'Mineral deposits encrusted the ledge by dissolving completely and leaving the stone perfectly bare.','Mineral deposits dissolved from the ledge, leaving the stone bare.','完全溶解并留下裸石与形成覆盖层相反。',[
Q('encrust',1,1,'To encrust a surface with salt is to?','cover it with a crusty layer of salt','wash every salt grain away','leave the surface untouched','encrust 指结成硬壳或覆盖一层物质。'),Q('encrust',2,1,'A necklace encrusted with jewels is?','covered with many jewels','stripped of every jewel','made only from uncut wood','encrust with jewels 表示表面镶满宝石。'),Q('encrust',3,1,'Which natural process can encrust a pipe?','mineral buildup forms a hard layer','all deposits vanish without trace','the pipe is made shorter by measurement','矿物沉积形成硬层会包覆管道。'),Q('encrust',4,1,'Choose the correct meaning: “Mud encrusted the boots.”','Mud formed a coating on the boots.','The boots removed all mud from the field.','The boots turned into water.','泥在靴面结成覆盖层。')]);
P('encumber','encumber came through Old French encombrer, “block or burden,” ultimately linked to a barrier or obstacle.',C('encumber.s1','登山装备','A heavy pack encumbered the climbers on the steep ascent, slowing each step and making the narrow path harder to cross.','沉重的背包拖累登山者攀爬陡坡，减慢了每一步，也让狭窄山路更难通过。','A heavy pack encumbered the climbers / on the steep ascent / slowing each step / and making the narrow path harder to cross.','encumber 是及物动词，指负重或障碍使人行动、进展变困难。','背包让登山者变慢、难以前进，符合阻碍义 s1。'),'The light pack encumbered the climbers by making every step faster and easier.','The light pack helped the climbers by making every step faster and easier.','让行动更快更容易是帮助，不是阻碍。',[
Q('encumber',1,1,'Heavy luggage may encumber a traveler by?','making movement difficult','making the trip cost nothing','showing the traveler a map','encumber 指拖累并妨碍行动。'),Q('encumber',2,1,'Which situation is encumbering?','red tape delays a project at every stage','a clear path speeds the crew’s work','a light tool fits easily into a pocket','繁琐程序不断拖慢项目进展。'),Q('encumber',3,1,'A debt can encumber a business by?','limiting its ability to invest or expand','guaranteeing unlimited free money','removing all accounting duties','债务可能拖累企业扩张。'),Q('encumber',4,1,'The closest opposite of encumber is?','facilitate','burden','impede','facilitate 表示促进，与阻碍相反。')]);
P('encyclopaedia','encyclopaedia came through French from medieval Latin encyclopaedia, from Greek enkyklios paideia, “all-round education.”',C('encyclopaedia.s1','图书馆检索','The reference desk kept an encyclopaedia beside the atlas, allowing students to consult concise entries on unfamiliar historical events.','参考台把百科全书放在地图册旁，学生可以查阅陌生历史事件的简明条目。','The reference desk kept an encyclopaedia beside the atlas / allowing students to consult / concise entries / on unfamiliar historical events.','encyclopaedia 是英式拼写的百科全书；美式拼写通常为 encyclopedia。','按主题提供各类知识条目的参考书符合 s1。'),'The encyclopaedia contained only blank pages and no subject entries or knowledge.','The blank notebook contained no subject entries or reference material.','没有任何知识条目的空白笔记本不能称为百科全书。',[ 
Q('encyclopaedia',1,1,'An encyclopaedia is a reference work that?','summarizes knowledge by subject','lists only one person’s daily meals','contains only blank paper','百科全书按主题汇集知识。'),Q('encyclopaedia',2,1,'A student might consult an encyclopaedia to?','find a concise overview of an unfamiliar topic','apply for a passport','borrow a bicycle','查阅陌生主题的概述是百科全书用途。'),Q('encyclopaedia',3,1,'Which spelling is a common British variant?','encyclopaedia','encyclopædicallye','encyclopaedianism','encyclopaedia 是英式常见拼法。'),Q('encyclopaedia',4,1,'An encyclopaedia entry on volcanoes would likely provide?','organized factual information about volcanoes','a personal diary with no reference facts','only a list of bus departures','条目提供按主题组织的知识。')],'spelling');
P('endangered','endangered is formed from endanger plus -ed; endanger combines en- with danger, from Old French dangier.',C('endangered.s1','野生动物保护','The island fox is endangered because its population remains small and vulnerable to disease, habitat loss, and introduced predators.','岛狐濒临灭绝，因为种群数量仍然很少，容易受到疾病、栖息地丧失和外来捕食者的威胁。','The island fox is endangered / because its population remains small and vulnerable / to disease, habitat loss, and introduced predators.','endangered 常作形容词，描述数量少到有灭绝风险的物种；也可泛指处于危险中的人或事物。','种群小且受多重威胁，说明物种可能灭绝，符合 s1。'),'The endangered bird faced no threats and its population was increasing rapidly everywhere.','The thriving bird faced no threats and its population was increasing rapidly everywhere.','没有威胁且数量快速增长不符合濒危状态。',[
Q('endangered',1,1,'An endangered species is at risk of?','dying out','becoming a new mountain range','being domesticated by definition','endangered species 指有灭绝风险的物种。'),Q('endangered',2,1,'Which factor can leave a species endangered?','loss of its habitat','unlimited secure habitat','a rapidly growing population with no threats','栖息地丧失会增加灭绝风险。'),Q('endangered',3,1,'Conservation workers protect endangered animals to?','help prevent their extinction','ensure they have no offspring','remove them from every habitat','保护工作旨在防止物种灭绝。'),Q('endangered',4,1,'An endangered species usually has?','a small or threatened population','a guaranteed unlimited population','no connection to survival risks','濒危物种的种群受威胁或规模较小。')]);
P('endear','endear combines en- with dear, from Old English deore, “precious or beloved”; it means make someone feel affection for a person or thing.',C('endear.s1','人物评价','Her patience with nervous new students endeared her to the whole class, who trusted her even when lessons became difficult.','她耐心对待紧张的新生，因此赢得全班的喜爱；即使课程变难，学生们也信任她。','Her patience with nervous new students / endeared her to the whole class / who trusted her / even when lessons became difficult.','常见结构是 endear someone to someone：某种行为使某人受到另一人喜爱。','她的耐心让全班喜欢并信任她，符合 s1。'),'His rude treatment endeared him to the team, so every member disliked and avoided him.','His rude treatment alienated him from the team, so members disliked and avoided him.','粗鲁行为使人疏远而不是赢得喜爱。',[
Q('endear',1,1,'To endear yourself to a group is to?','make the group feel affection for you','force everyone to leave the group','measure the group’s height','endear 表示使自己赢得他人喜爱。'),Q('endear',2,1,'A thoughtful gift may endear a neighbor to you by?','making the neighbor feel warmly toward you','making the neighbor forget your name','blocking your doorway','贴心举动可以使邻居对你有好感。'),Q('endear',3,1,'Choose the natural pattern.','Her kindness endeared her to the children.','Her kindness endeared the children from her.','Her kindness endeared to the children her.','常见搭配为 endear sb to sb。'),Q('endear',4,1,'Which behavior is most likely to endear a leader to staff?','listening fairly and helping when problems arise','taking credit for every mistake','ignoring all questions','公平倾听并提供帮助会赢得员工好感。')]);
P('endemic','endemic came from Greek endemos, “in one’s country,” formed from en- “in” and demos “people.”',C('endemic.s2','流行病学','Malaria is endemic in parts of the region, where local health clinics monitor cases throughout the year rather than only during a brief outbreak.','疟疾在该地区部分地方呈地方性流行，当地诊所全年监测病例，而非只在短暂暴发期关注。','Malaria is endemic in parts of the region / where local health clinics monitor cases / throughout the year / rather than only during a brief outbreak.','endemic 可形容某地或群体中长期常见的事物，也可作名词表示地方病；此处是疾病义 s2。','全年在当地持续发现病例，说明疾病长期存在于该区域，符合 s2。'),'The disease was endemic in the region because it appeared once in a distant country and never occurred locally.','The disease was imported into the region after appearing abroad but had never been locally established.','从未在当地出现不能称为当地地方性疾病。',[
Q('endemic',1,2,'An endemic disease is one that?','regularly occurs in a particular region','has been eliminated from every region','appears only in one fictional story','地方病是在特定地区持续存在的疾病。'),Q('endemic',2,1,'A plant endemic to an island is?','native or regularly found there','recently imported for one day','unable to grow anywhere','endemic 可描述某地固有或常见的事物。'),Q('endemic',3,2,'Which situation is endemic rather than a single outbreak?','cases recur locally over many years','one traveler becomes ill abroad and no local cases occur','a disease has vanished completely','多年反复的本地病例符合地方性流行。'),Q('endemic',4,1,'The adjective endemic most directly links something to?','a particular place or population','a temporary object’s color','a person’s job title only','endemic 强调特定区域或群体关联。')]);
P('endlessly','endlessly is formed from endless plus -ly; endless combines end with -less, “without.”',C('endlessly.s1','重复工作','The conveyor moved endlessly through the night, carrying sealed boxes past the inspection station one after another.','传送带整夜不停地运转，把一箱箱封好的箱子依次送过检查站。','The conveyor moved endlessly through the night / carrying sealed boxes / past the inspection station / one after another.','endlessly 作副词，表示持续很久、仿佛看不到尽头；也可指重复不休。','整夜持续运转、箱子接连不断，体现 s1。'),'The conveyor moved endlessly for only one second and then stopped forever.','The conveyor moved briefly for one second and then stopped forever.','只持续一秒便停止不能称为无休止地持续。',[
Q('endlessly',1,1,'A road that seems to continue endlessly?','appears to have no visible end','ends immediately at the first corner','is exactly one metre long by definition','endlessly 表示似乎看不到尽头。'),Q('endlessly',2,1,'Someone who talks endlessly is likely to?','continue talking for a very long time','say one word and stop','remain completely silent','副词可形容冗长不休地做某事。'),Q('endlessly',3,1,'Which is an endless repetition?','the same alarm rings again and again','a single bell sounds once','the machine is switched off','反复响个不停体现 endless repetition。'),Q('endlessly',4,1,'The word endlessly is closest to?','without an apparent end','only once','under a strict deadline','它表示没有明显终点地持续。')]);
P('endocrine','endocrine combines Greek endon “within” and krinein “separate or secrete”; it concerns glands releasing hormones internally.',C('endocrine.s1','生物课程','The endocrine system releases hormones into the bloodstream, helping regulate growth, metabolism, and other body processes.','内分泌系统把激素释放到血液中，帮助调节生长、新陈代谢和其他身体过程。','The endocrine system releases hormones / into the bloodstream / helping regulate growth / metabolism, and other body processes.','endocrine 作形容词，指直接向血液分泌激素或与这类腺体系统有关。','激素进入血流并调节身体过程，符合内分泌义 s1。'),'Endocrine glands release their secretions only through ducts onto the skin surface.','Exocrine glands release secretions through ducts onto a surface.','直接进入血液是 endocrine 的特征；经导管排出对应 exocrine。',[
Q('endocrine',1,1,'An endocrine gland releases hormones into?','the bloodstream','a hollow hair shaft only','the outside air directly','内分泌腺将激素直接分泌入血流。'),Q('endocrine',2,1,'Which is an endocrine function?','hormonal regulation of metabolism','mechanical grinding of food by teeth','reflection of light from a mirror','激素调节新陈代谢属于内分泌系统功能。'),Q('endocrine',3,1,'Endocrine differs from exocrine because endocrine secretions?','enter the blood rather than travel through ducts to a surface','are always solid and never chemical','are released only into the stomach by a tube','内分泌分泌物进入血流，而非经导管到表面。'),Q('endocrine',4,1,'A specialist might study endocrine glands to understand?','hormones and body regulation','the design of bridges','the history of printed maps','内分泌腺与激素调节相关。')]);
P('endocrinology','endocrinology combines endocrine with -logy, “study”; endocrine joins Greek endon “within” and krinein “secrete.”',C('endocrinology.s1','专科门诊','Endocrinology examines hormones and the glands that produce them, so the clinic evaluated thyroid levels and related symptoms.','内分泌学研究激素及其分泌腺体，因此诊所检测了甲状腺指标和相关症状。','Endocrinology examines hormones / and the glands that produce them / so the clinic evaluated thyroid levels / and related symptoms.','endocrinology 是医学分支，研究激素、产生激素的腺体及相关疾病。','甲状腺指标和激素腺体属于内分泌学研究内容，符合 s1。'),'The endocrinology clinic studied only road construction and bridge maintenance.','The civil-engineering clinic studied road construction and bridge maintenance.','道路和桥梁属于土木工程，不是内分泌学。',[
Q('endocrinology',1,1,'Endocrinology is the medical study of?','hormones and hormone-producing glands','rocks and mineral deposits','ancient legal documents','内分泌学研究激素及其腺体。'),Q('endocrinology',2,1,'An endocrinologist may investigate a patient’s?','thyroid hormone levels','shoe size only','favorite musical key','甲状腺激素属于该学科关注对象。'),Q('endocrinology',3,1,'The suffix -logy in endocrinology suggests?','a field of study','a plural form','a past-tense action','-logy 表示研究学科。'),Q('endocrinology',4,1,'Which topic belongs in an endocrinology journal?','how insulin-producing cells regulate blood sugar','how glaciers carve valleys','how judges interpret property deeds','胰岛素与血糖调节是内分泌学主题。')]);
P('endogenous','endogenous combines Greek endon “within” and -genous, “produced by”; it means arising from within a system or organism.',C('endogenous.s1','医学研究','The researchers separated endogenous cortisol produced by the body from the synthetic hormone administered during the trial.','研究人员把身体自身产生的内源性皮质醇与试验中给药的合成激素区分开来。','The researchers separated endogenous cortisol / produced by the body / from the synthetic hormone / administered during the trial.','endogenous 作形容词表示由机体或系统内部产生，与外部输入的 exogenous 相对。','皮质醇由身体本身产生，符合内源性 s1。'),'The lab called a hormone endogenous even though it was supplied only by an outside injection and not produced by the body.','The lab called the injected hormone exogenous because it came from outside the body.','仅由外部注射提供的物质不是机体内部产生的内源性物质。',[
Q('endogenous',1,1,'An endogenous chemical is produced?','within the organism or system','only by an outside factory','by a neighboring country’s government','endogenous 表示由内部产生。'),Q('endogenous',2,1,'Which hormone source is endogenous?','a hormone made by the patient’s own gland','a synthetic dose injected from outside','a medicine mailed by a clinic','自身腺体产生的激素属于内源性。'),Q('endogenous',3,1,'Endogenous is the opposite of?','exogenous','internal','native','exogenous 表示来自外部，与之相反。'),Q('endogenous',4,1,'In an economic model, an endogenous variable is determined?','within the model itself','only by an unrelated external system','by spelling rules alone','模型内部决定的变量称 endogenous。')]);
P('endoscopy','endoscopy combines endo- “within” with -scopy “examination by viewing,” ultimately from Greek skopein “look at.”',C('endoscopy.s1','消化科检查','During endoscopy, the physician guided a thin flexible instrument through the patient’s mouth to examine the upper digestive tract.','进行内窥镜检查时，医生把一根细长柔软的器械从病人口中送入，以检查上消化道。','During endoscopy / the physician guided a thin flexible instrument / through the patient’s mouth / to examine the upper digestive tract.','endoscopy 是通过 endoscope 观察身体内部的检查；它指检查过程，不是切除手术本身。','医生以带摄像设备的细软器械观察体内，符合 s1。'),'The endoscopy examined the digestive tract by viewing only the outside of the patient’s clothing.','The physical examination inspected the patient’s clothing without using an endoscope.','只看衣物没有用内窥镜查看身体内部，不能称为 endoscopy。',[
Q('endoscopy',1,1,'Endoscopy is a procedure for?','looking inside the body with an endoscope','measuring the body’s height with a ruler','testing the color of clothing','endoscopy 指用内窥镜观察体内。'),Q('endoscopy',2,1,'During a gastrointestinal endoscopy, a doctor may?','view the digestive tract through a flexible instrument','replace every organ with a photograph','inspect only a patient’s shoes','软式内窥镜可观察消化道。'),Q('endoscopy',3,1,'The ending -scopy suggests?','visual examination','a person who sells medicine','a surgical cut itself','-scopy 表示通过观察进行检查。'),Q('endoscopy',4,1,'Which tool is central to endoscopy?','an endoscope with a viewing system','a kitchen scale','a road map','内窥镜是检查的核心器械。')]);
P('endoskeleton','endoskeleton combines endo- “within” and skeleton, from Greek skeletos, “dried-up body.”',C('endoskeleton.s1','动物解剖','Unlike an insect’s outer shell, a human endoskeleton lies inside the body and supports movement through the bones and joints.','与昆虫的外壳不同，人的内骨骼位于身体内部，通过骨骼和关节支撑运动。','Unlike an insect’s outer shell / a human endoskeleton lies inside the body / and supports movement / through the bones and joints.','endoskeleton 是位于身体内部的支撑骨架；昆虫外部的硬壳叫 exoskeleton。','骨骼和关节在体内支撑人体，对应 s1。'),'A human endoskeleton is an external shell covering the body like an insect’s armor.','A human exoskeleton would be an external shell, but humans have an internal skeleton.','人类骨架位于体内，不是覆盖体表的外骨骼。',[
Q('endoskeleton',1,1,'An endoskeleton is located?','inside an organism’s body','only on the outer surface','in the surrounding soil','endo- means within; an endoskeleton is internal. '),Q('endoskeleton',2,1,'Human bones form an?','endoskeleton','exoskeleton','external skin layer','人的骨骼构成体内支撑框架。'),Q('endoskeleton',3,1,'An insect’s hard outer covering is an?','exoskeleton','endoskeleton','endocrine gland','昆虫外部硬壳是外骨骼。'),Q('endoskeleton',4,1,'What is a key function of an endoskeleton?','supporting the body and enabling movement','secreting hormones into blood','digesting food in the stomach','骨骼支撑身体并通过关节帮助运动。')]);
P('endotherm','endotherm combines endo- “within” and therm, from Greek thermos “warm”; it is an animal generating most body heat internally.',C('endotherm.s1','动物生理','A small endotherm can maintain a relatively stable body temperature in cool weather by producing heat through metabolism.','小型内温动物能通过新陈代谢产热，在凉爽天气中维持相对稳定的体温。','A small endotherm / can maintain a relatively stable body temperature / in cool weather / by producing heat through metabolism.','endotherm 是主要依靠自身代谢维持体温的动物；与 ectotherm（体温较依赖外界）相对。','动物靠体内代谢产热维持稳定温度，符合 s1。'),'The lizard was an endotherm because its temperature changed entirely with the sun and surroundings.','The lizard was an ectotherm because its temperature depended strongly on external heat.','体温高度依赖外部日照是 ectotherm 的特点。',[
Q('endotherm',1,1,'An endotherm maintains warmth mainly through?','heat generated by its own metabolism','the temperature of nearby rocks alone','a coat of paint','endotherm 主要由体内代谢产生热量。'),Q('endotherm',2,1,'Which animal is commonly an endotherm?','a bird maintaining body heat','a lizard warming only in sunlight','a rock heated by a lamp','鸟类通常通过自身代谢维持体温。'),Q('endotherm',3,1,'Endotherm contrasts with an animal whose temperature depends strongly on?','external environmental heat','its own internal metabolism only','the length of its tail','外温动物更依赖环境热量。'),Q('endotherm',4,1,'The prefix endo- in endotherm points to heat produced?','within the body','outside the planet','under the ocean only','endo- 表示内部，指体内产热。')]);
P('endotoxin','endotoxin combines endo- “within” with toxin, from Latin toxicum “poison”; it is a toxic component of some bacterial cell walls.',C('endotoxin.s1','微生物学','The laboratory detected endotoxin released from bacterial cell material after the bacteria died, so the sample required special handling.','细菌死亡后，实验室检测到从其细胞物质中释放出的内毒素，因此样品需要特殊处理。','The laboratory detected endotoxin / released from bacterial cell material / after the bacteria died / so the sample required special handling.','endotoxin 指细菌细胞结构中的毒性成分，细菌死亡或破裂时可释放；区别于活菌主动分泌的 exotoxin。','毒素随细菌死亡后细胞物质释放，符合内毒素义 s1。'),'The endotoxin was described as a toxin actively secreted by living bacteria, unrelated to their cell structure.','The exotoxin was described as a toxin actively secreted by living bacteria.','活菌主动分泌的毒素通常称 exotoxin；endotoxin 与细胞成分相关。',[
Q('endotoxin',1,1,'An endotoxin is associated with?','toxic material forming part of certain bacterial cells','a harmless hormone from a human gland','a chemical paint on a metal surface','内毒素是某些细菌细胞结构中的毒性物质。'),Q('endotoxin',2,1,'Endotoxin may be released when bacteria?','die or break apart','turn into a plant','are translated into another language','细菌死亡或破裂可释放内毒素。'),Q('endotoxin',3,1,'A toxin actively secreted by living bacteria is more typically called?','an exotoxin','an endoskeleton','an endowment','活菌分泌毒素与 endotoxin 相区别，常称 exotoxin。'),Q('endotoxin',4,1,'In endotoxin, the prefix endo- points to a toxin?','within the bacterial cell structure','outside every biological system','used only in construction','内毒素名称提示其与细胞内部结构相关。')]);
P('endowment','endowment comes through Old French endouer from Latin dotare, “endow”; it can mean a lasting gift or a natural ability.',C('endowment.s1','教育基金','The university’s endowment funded scholarships each year, using investment income from donations that former graduates had contributed.','大学捐赠基金每年资助奖学金，资金来自历届毕业生捐赠的投资收益。','The university’s endowment funded scholarships each year / using investment income / from donations / that former graduates had contributed.','endowment 可指为机构提供持续收入的捐赠基金；天赋义见 s2。','捐赠被投资并持续资助奖学金，体现机构基金义 s1。'),'The university’s endowment was a one-time bill that students had to pay to receive a scholarship.','The university’s tuition bill was a payment students had to make for their studies.','基金是机构获得的捐赠资产，不是学生为上学支付的一次账单。',[
Q('endowment',1,1,'A university endowment is generally?','a donated fund invested to provide continuing income','a tax students pay for each textbook','an employee’s weekly schedule','捐赠基金用于持续为机构提供收入。'),Q('endowment',2,2,'A natural endowment is?','an inborn ability or quality','a donation made only to a university','a deadline for filing a form','endowment 也可指天赋或天然品质。'),Q('endowment',3,1,'Income from an endowment may support?','scholarships and institutional programs','the personal debts of every donor','weather changes in another country','基金收益可支持奖学金或机构项目。'),Q('endowment',4,2,'A child with an unusual musical endowment has?','a natural musical gift','a legally restricted account only','no musical ability at all','这里的 endowment 指先天才能。')]);
P('endpoint','endpoint combines end and point; it names the place, time, or value at which a line, period, or process stops.',C('endpoint.s1','项目进度','The team set a clear endpoint for the pilot, agreeing to review results after six months before deciding whether to expand it.','团队为试点项目设定了明确终点，同意六个月后评估结果，再决定是否扩大。','The team set a clear endpoint for the pilot / agreeing to review results / after six months / before deciding whether to expand it.','endpoint 可指路线或线段的端点，也可指时间、过程或任务的终点。','六个月后进行最终评估并作出是否扩大的决定，构成项目终点 s1。'),'The endpoint of the trial was its starting date, before any work or review had occurred.','The starting point of the trial was its first date, before the work began.','终点是过程结束处，不是开始处。',[
Q('endpoint',1,1,'The endpoint of a road is?','the place where the road ends','the point where it was first planned','a vehicle traveling on it','endpoint 指线段或路线停止的端点。'),Q('endpoint',2,1,'A project endpoint marks?','the stage at which the project concludes','the project’s unrelated lunch break','the first employee hired','项目终点标记任务结束处。'),Q('endpoint',3,1,'In geometry, a line segment has?','two endpoints','no ends at all','one circular surface','有限线段有两个端点。'),Q('endpoint',4,1,'Which phrase uses endpoint naturally?','the endpoint of a testing period','the endpoint of a person’s shoe as a job title','the endpoint of a color','testing period 的终点是自然搭配。')]);
P('endue','endue entered English through Middle English and Old French enduer, from Latin induere, “put on”; formally it means invest someone with a quality.',C('endue.s1','人物描写','The author endued the heroine with unusual patience, allowing her to listen calmly while the other characters argued.','作者赋予女主人公非凡的耐心，使她在其他角色争论时仍能平静倾听。','The author endued the heroine / with unusual patience / allowing her to listen calmly / while the other characters argued.','endue 是正式、较少见的及物动词，常用 endue someone with a quality or power。','角色被赋予耐心这一品质，符合 s1。'),'The story endued the heroine with patience by taking away every ability and quality she had.','The story stripped the heroine of patience by taking away the quality she had.','剥夺某种品质与赋予品质相反。',[
Q('endue',1,1,'To endue someone with courage is to?','give that person the quality of courage','remove every quality from that person','measure the person’s height','endue someone with 表示赋予某种品质。'),Q('endue',2,1,'Which sentence uses endue correctly?','The tale endued the hero with wisdom.','The tale endued wisdom from the hero.','The tale endued the hero of all wisdom.','常见句型为 endue sb with a quality。'),Q('endue',3,1,'Endue is closest in meaning to?','endow','deprive','erase','endow 也表示赋予或授予。'),Q('endue',4,1,'The word endue is best described as?','a formal, uncommon verb','a common name for a kitchen tool','an adjective for a river','endue 语体较正式且不常见。')]);
P('endurable','endurable is formed from endure plus -able; endure came through Old French from Latin indurare, “make hard or last.”',C('endurable.s1','工作环境','The noise became endurable after the crew installed panels that reduced the sharpest sounds from the nearby machinery.','附近机器的刺耳噪声被工人装设的隔音板削弱后，变得可以忍受。','The noise became endurable / after the crew installed panels / that reduced the sharpest sounds / from the nearby machinery.','endurable 形容令人不适但仍能忍受的情况；不表示舒适或毫无困难。','噪声仍存在但被减弱到可以承受，符合 s1。'),'The endurable heat was so painful that nobody could survive even a moment in the room.','The unbearable heat was so painful that nobody could survive even a moment in the room.','无人能忍受的高温是 unbearable，不是 endurable。',[
Q('endurable',1,1,'An endurable delay is?','unpleasant but still possible to tolerate','so severe that it cannot be tolerated','a delay that never happens','endurable 表示虽不舒服但尚能忍受。'),Q('endurable',2,1,'A task becomes endurable when?','reasonable support makes its difficulty bearable','it becomes completely impossible','nobody is allowed to attempt it','帮助使困难变得可以承受。'),Q('endurable',3,1,'Which is closest to endurable?','bearable','intolerable','invisible','bearable 是可忍受的。'),Q('endurable',4,1,'The word endurable does not necessarily mean?','pleasant or enjoyable','possible to put up with','not ideal but bearable','可忍受不等于愉快或令人享受。')]);
P('energize','energize is formed from energy plus -ize; energy comes through French from Greek energeia, “activity.”',C('energize.s1','团队训练','The short warm-up energized the players, and they began the final drill with sharper focus and quicker movement.','简短热身让队员们充满活力，他们带着更集中的注意力和更快的动作开始最后一轮训练。','The short warm-up energized the players / and they began the final drill / with sharper focus / and quicker movement.','energize 可指使人更有活力或意愿 s1；为机器或设备供能是 s2。','热身提高了队员的活力与专注度，符合 s1。'),'The long warm-up energized the players by leaving them exhausted and unable to move.','The long warm-up exhausted the players, leaving them unable to move.','精疲力竭、无法行动是耗尽体力，不是激发活力。',[
Q('energize',1,1,'A lively song may energize a team by?','making the members feel more active','removing every source of motivation','turning the team into a building','energize 表示使人更有活力。'),Q('energize',2,2,'A battery can energize a device by?','supplying it with electrical power','telling its story in a short paragraph','covering it with dust','机器义指给设备供电。'),Q('energize',3,1,'Which sentence uses the motivational sense?','The coach’s praise energized the tired runners.','The cable energized the lamp with current.','The breaker disconnected the motor.','教练的表扬激励跑者，对应 s1。'),Q('energize',4,2,'Solar panels energize the remote sensor, meaning they?','supply the sensor with power','make the sensor feel proud','reduce its size to zero','太阳能板为传感器供能。')]);
P('enervate','enervate comes from Latin enervare, “weaken or deprive of sinews”; modern use means drain strength or energy.',C('enervate.s1','酷热天气','The humid afternoon enervated the workers, who took frequent water breaks and moved equipment more slowly than usual.','闷热的午后使工人们筋疲力尽，他们频繁喝水休息，搬运设备也比平时慢。','The humid afternoon / enervated the workers / who took frequent water breaks / and moved equipment more slowly than usual.','enervate 作动词表示使人衰弱、无力；形容词用法“衰弱的”见 s2。','闷热导致工人乏力、动作变慢，体现使衰弱义 s1。'),'The heat enervated the crew by giving everyone renewed strength and boundless energy.','The cool break revived the crew and gave everyone renewed strength.','恢复精力是 revive 的意思，与 enervate 使人衰弱相反。',[
Q('enervate',1,1,'To enervate a person is to?','drain the person’s strength or energy','make the person more energetic','give the person a formal title','enervate 表示使人衰弱无力。'),Q('enervate',2,2,'An enervate and exhausted patient is?','weak and lacking vigor','energetic and vigorous','newly appointed to office','形容词义表示虚弱无力。'),Q('enervate',3,1,'Which condition may enervate hikers?','prolonged heat and dehydration','a restful night and cool air','a short encouraging speech','酷热和脱水可能耗尽体力。'),Q('enervate',4,2,'An enervate response would sound?','weak and lacking force','decisive and full of energy','like a loud machine','形容词义可描述缺乏活力的反应。')]);
P('enervation','enervation is formed from enervate plus -ion; enervate comes from Latin enervare, “weaken.”',C('enervation.s1','耐力分析','By the end of the long shift, the crew’s enervation was clear in their slow movements and difficulty concentrating on routine checks.','长班结束时，工人们行动迟缓、难以集中注意力做例行检查，疲惫衰弱十分明显。','By the end of the long shift / the crew’s enervation was clear / in their slow movements / and difficulty concentrating on routine checks.','enervation 是名词，表示体力、活力或精神精力的减弱、衰竭。','行动变慢且注意力下降体现活力耗损，符合 s1。'),'The enervation restored the crew’s stamina and made them stronger than before.','The recovery restored the crew’s stamina and made them stronger than before.','恢复耐力是康复，不是体力衰弱。',[
Q('enervation',1,1,'Enervation refers to?','loss of strength or vigor','a sudden increase in energy','a formal promise to marry','enervation 表示活力或力量的减弱。'),Q('enervation',2,1,'Which sign may show enervation after a shift?','slowed movement and poor concentration','renewed strength after rest','a higher salary in a new job','动作迟缓和难以集中注意力体现疲弱。'),Q('enervation',3,1,'The enervation caused by heat left the hikers?','weak and drained','refreshed and energetic','legally married','热导致精力耗尽。'),Q('enervation',4,1,'Which word is closest to enervation?','debilitation','invigoration','appointment','debilitation 表示衰弱。')]);
P('enforcement','enforcement is formed from enforce plus -ment; enforce came through Old French enforcier, “strengthen or compel.”',C('enforcement.s1','交通管理','Stricter enforcement of the speed limit reduced crashes after officers began monitoring the dangerous curve every evening.','警方开始每晚监测危险弯道后，严格执行限速规定减少了事故。','Stricter enforcement of the speed limit / reduced crashes / after officers began monitoring / the dangerous curve every evening.','enforcement 指确保法律、规则或协议得到遵守的执行或强制实施。','监测并执行限速规定以确保驾驶者遵守，符合 s1。'),'The enforcement of the speed limit meant officers stopped checking it and allowed every driver to ignore it.','The suspension of speed-limit enforcement meant officers stopped checking it.','停止检查并允许违反是暂停执法，而非执行。',[
Q('enforcement',1,1,'Enforcement of a law means?','making sure people obey it','removing it from every legal code','writing a poem about it','enforcement 是确保规则得到遵守。'),Q('enforcement',2,1,'Which action is law enforcement?','officers investigate a reported violation','a clerk decorates a courthouse','a judge chooses a lunch menu','调查违法行为是执法活动。'),Q('enforcement',3,1,'A school’s enforcement of a safety rule includes?','consistently applying the rule when it is broken','announcing the rule but never applying it','deleting all safety instructions','稳定落实规则属于执行。'),Q('enforcement',4,1,'Choose the natural phrase.','enforcement of an agreement','enforcement of a sandwich flavor','enforcement across a calendar color','常见搭配 enforcement of a law/rule/agreement。')]);
P('enforcer','enforcer is formed from enforce plus the agent suffix -er; it names a person who compels compliance or respect for rules or debts.',C('enforcer.s1','体育比赛','The league’s rules enforcer warned the players after repeated illegal tackles, then referred the worst case to the disciplinary panel.','联赛规则执行人员在多次出现非法擒抱后警告了球员，并把最严重的情况移交纪律小组。','The league’s rules enforcer warned the players / after repeated illegal tackles / then referred the worst case / to the disciplinary panel.','enforcer 指负责促使规则或债务得到遵守的人；某些语境中也含威胁强制的意味。','警告违规者并上报纪律小组，体现执行规则者 s1。'),'The rules enforcer encouraged the team to ignore every rule and never reported violations.','The rules enforcer applied the rules and reported repeated violations.','鼓励忽视规则与执行者的职责相反。',[
Q('enforcer',1,1,'A rules enforcer is someone who?','makes sure rules are obeyed','writes rules but never checks them','removes all rules from a league','enforcer 指负责执行规则的人。'),Q('enforcer',2,1,'Which person might act as an enforcer?','an officer collecting a legally owed debt','a tourist choosing a scenic route','a painter mixing colors','催收应付债务的人可充当 enforcer。'),Q('enforcer',3,1,'In sport, a league enforcer may?','penalize repeated rule violations','award points for breaking the rules','design the players’ shoes only','体育规则执行人员会处理反复违规。'),Q('enforcer',4,1,'The suffix -er in enforcer points to?','a person who performs an action','a past-tense action','a place containing water','-er 常表示执行动作的人。')]);
P('enfranchise','enfranchise came through Old French enfranchir, “make free,” from franc, “free”; it often means grant voting rights.',C('enfranchise.s1','选举史','The reform enfranchised women over twenty-one, giving them the right to register and vote in national elections.','这项改革赋予二十一岁以上女性选举权，使她们可以登记并参加全国选举投票。','The reform enfranchised women over twenty-one / giving them the right / to register and vote / in national elections.','enfranchise 是及物动词，表示给予公民权，尤其指授予选举权；常见宾语为群体。','法律改革让女性获得登记和投票的权利，符合 s1。'),'The reform enfranchised women by barring them from the voter register and forbidding them to vote.','The reform disenfranchised women by barring them from the voter register and forbidding them to vote.','剥夺登记和投票权叫 disenfranchise，与赋权相反。',[
Q('enfranchise',1,1,'To enfranchise a group is to?','grant it political rights, especially the vote','remove its right to vote','appoint it as a private company','enfranchise 尤其表示授予选举权。'),Q('enfranchise',2,1,'A law enfranchised new citizens when it?','allowed them to register and vote','deleted them from the voter roll','closed every polling place to them','允许登记并投票体现赋予选举权。'),Q('enfranchise',3,1,'Which word is the opposite of enfranchise?','disenfranchise','empower','enroll','disenfranchise 表示剥夺投票权。'),Q('enfranchise',4,1,'A campaign to enfranchise adults seeks to?','extend voting rights to them','prevent them from entering public life','make voting records disappear','该运动旨在扩大投票权。')]);
P('engaged','engaged is the past participle of engage, from Old French engagier, “pledge”; it can mean occupied or formally promised in marriage.',C('engaged.s2','婚讯','The couple announced that they were engaged after accepting each other’s proposal, and their families began planning a small ceremony.','两人接受彼此的求婚后宣布订婚，双方家庭开始筹划一场小型仪式。','The couple announced / that they were engaged / after accepting each other’s proposal / and their families began planning a small ceremony.','engaged 可表示忙于某事或设备正被使用 s1，也可表示已正式订婚 s2。','接受求婚并筹划婚礼明确体现已订婚义 s2。'),'The couple said they were engaged even though neither had agreed to marry and both rejected the proposal.','The couple said they were not engaged because neither had agreed to marry.','双方都拒绝求婚，不可能已正式答应结婚。',[
Q('engaged',1,2,'A couple who are engaged have?','formally agreed to marry','already divorced','booked a business appointment only','engaged 的婚姻义是已订婚。'),Q('engaged',2,1,'A person engaged in research is?','busy doing research','formally promised to marry the research','unavailable because the research is a wedding','engaged in 表示忙于某活动。'),Q('engaged',3,1,'A phone line is engaged when it is?','in use and unavailable for another call','turned into a wedding ring','not connected to any network','线路 engaged 指正在占用中。'),Q('engaged',4,2,'Which sentence means “已订婚”?','They became engaged last spring.','They were engaged in a long debate.','The phone line is engaged.','became engaged 表示订婚。')]);
P('engagement','engagement is formed from engage plus -ment; depending on context, it can mean a promise to marry, an appointment, or a military encounter.',C('engagement.s3','战争史','The brief engagement ended when both armies withdrew from the river crossing after dark.','短暂交战在天黑后双方军队撤离渡口时结束。','The brief engagement ended / when both armies withdrew / from the river crossing / after dark.','engagement 可指订婚 s1、预先约定的会面 s2，或军队之间的交战 s3。','双方军队交火后撤离，明确为军事交战义 s3。'),'The armies’ engagement was a planned wedding promise with no fighting between them.','The armies’ engagement was a brief battle with fighting between them.','军队之间的交火是战斗，不是婚姻承诺。',[
Q('engagement',1,1,'A couple’s engagement is?','a formal promise to marry','a completed divorce','a battle between two armies','订婚是正式约定结婚。'),Q('engagement',2,2,'A business engagement at 10 a.m. is?','a scheduled appointment','a wedding ring','an unplanned military attack','engagement 也指预先约定的会面。'),Q('engagement',3,3,'A military engagement is?','a clash or battle between forces','a promise between spouses only','a university scholarship fund','军事义 engagement 指武装交战。'),Q('engagement',4,1,'“They announced their engagement” most likely means they?','plan to marry','have been fighting in a battle','have ended their employment','宣布 engagement 通常指已订婚。')]);
P('engaging','engaging is formed from engage plus -ing; the adjective describes a person or thing that holds attention in a charming way.',C('engaging.s1','课堂讲解','The lecturer’s engaging examples kept even the quiet students asking questions long after the scheduled class had ended.','讲师生动吸引人的例子让最安静的学生也在课程结束后仍不断提问。','The lecturer’s engaging examples / kept even the quiet students asking questions / long after / the scheduled class had ended.','engaging 常形容有魅力、能抓住兴趣的人、表达或活动。','学生持续专注并提问，说明例子吸引人，符合 s1。'),'The engaging speaker lost the audience immediately because nobody wanted to listen.','The dull speaker lost the audience immediately because nobody wanted to listen.','无人愿听说明演讲乏味，不是 engaging。',[
Q('engaging',1,1,'An engaging speaker is?','charming and able to hold listeners’ interest','dull and impossible to hear','legally required to marry','engaging 指生动有吸引力。'),Q('engaging',2,1,'Which is an engaging opening to a talk?','a vivid question that draws listeners in','a long list of unrelated numbers','silence followed by an empty slide','生动问题可以抓住听众兴趣。'),Q('engaging',3,1,'An engaging character in a novel is likely to?','make readers want to follow the story','prevent readers from understanding any event','appear only as punctuation','有吸引力的角色让读者愿意继续读。'),Q('engaging',4,1,'Choose the closest synonym for engaging.','captivating','tedious','unrelated','captivating 也表示吸引人的。')]);
P('engender','engender came through Old French engendrer from Latin ingenerare, “produce or bring forth.”',C('engender.s1','公共政策','Unclear rules engendered distrust among residents, who worried that different neighborhoods would be treated by different standards.','规则不清在居民中引发了不信任，他们担心不同社区会受到不同标准对待。','Unclear rules / engendered distrust among residents / who worried / that different neighborhoods would be treated by different standards.','engender 是及物动词，表示引起或造成某种情绪、状况或反应。','模糊规则导致居民不信任，体现造成反应义 s1。'),'The new evidence engendered no concern because it made everyone increasingly worried and fearful.','The new evidence engendered concern because it made people worried and fearful.','使人担忧就是引发 concern，不能说完全没有引发关切。',[
Q('engender',1,1,'To engender suspicion is to?','cause suspicion to arise','remove every reason for suspicion','hide a suspect in a room','engender 表示引起某种反应。'),Q('engender',2,1,'Which can engender public trust?','clear rules applied consistently','secret decisions with shifting standards','an unexplained delay','透明且一致的规则可建立信任。'),Q('engender',3,1,'In “the delay engendered frustration,” engendered means?','caused frustration','measured frustration','ended the delay','engendered 在此表示引起。'),Q('engender',4,1,'Choose a natural object of engender.','engender debate','engender a ruler into centimetres','engender the door from a room','engender 可带抽象结果名词作宾语。')]);
P('England','England comes from Old English Engla land, “land of the Angles,” one of the peoples who settled in Britain.',C('England.s1','地理常识','London is the capital of England, the largest country within the United Kingdom; England is not the name of the entire UK.','伦敦是英格兰的首府；英格兰是英国境内面积最大的构成国，但 England 并不是整个英国的名称。','London is the capital of England / the largest country within the United Kingdom / England is not the name / of the entire UK.','England 专指英格兰，是联合王国的组成部分；不要与 United Kingdom 或 Great Britain 混为一谈。','句中将英格兰与整个英国明确区分，符合 s1。'),'England is the name for the whole United Kingdom, including Scotland, Wales, and Northern Ireland.','The United Kingdom includes England, Scotland, Wales, and Northern Ireland.','England 是英国的组成部分之一，不等同于联合王国全境。',[ 
Q('England',1,1,'England is?','one country within the United Kingdom','the full name of the United Kingdom','a city in Scotland','England 是联合王国的组成国之一。'),Q('England',2,1,'What is the capital of England?','London','Cardiff','Edinburgh','英格兰首府是伦敦。'),Q('England',3,1,'Which statement is accurate?','Scotland and Wales are not part of England.','England includes all of Ireland by definition.','The UK and England are identical names.','苏格兰和威尔士不是英格兰的一部分。'),Q('England',4,1,'England should not be confused with?','the United Kingdom as a whole','London as its capital','a country within the UK','英格兰不等于整个联合王国。')],'confusable');
P('engrave','engrave came through Old French engraver, “carve or cut into”; figuratively it can mean fix something firmly in memory.',C('engrave.s1','珠宝制作','The jeweller engraved the date inside the silver locket, using a fine tool so the lettering would remain legible for years.','珠宝匠用细刻刀把日期刻在银吊坠内侧，使字迹多年后仍清晰可辨。','The jeweller engraved the date / inside the silver locket / using a fine tool / so the lettering would remain legible for years.','engrave 常用 engrave A on/in B，指把文字或图案刻入金属、石头或玻璃；牢牢记住是 s2。','日期被切刻在吊坠内侧，符合物理雕刻义 s1。'),'The jeweller engraved the date on the locket by wiping all marks away and leaving a smooth blank surface.','The jeweller polished the locket until its surface was blank and unmarked.','擦掉所有痕迹不会把日期刻上去。',[
Q('engrave',1,1,'To engrave a name on a ring is to?','cut the letters into its surface','wrap the ring in paper only','erase every mark from it','engrave 表示把文字刻入硬质表面。'),Q('engrave',2,2,'A warning engraved on someone’s memory is?','remembered very firmly','written on a metal plate only','forgotten immediately','比喻义指牢牢记住某事。'),Q('engrave',3,1,'Which material is commonly engraved?','metal','moving air','a spoken vowel','文字或图案可刻在金属上。'),Q('engrave',4,2,'The lesson was engraved in her mind means she?','will remember it strongly','carved her mind with a tool','has forgotten the lesson','固定短语比喻深深铭记。')]);

})();
